/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20251126-7","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"厚生委員会","time":"午前１０時１０分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"（仮称）小山七丁目障害者グループホームの開設時期の変更","agenda":"（仮称）小山七丁目障害者グループホームの開設時期の変更","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"工事費の高騰ということなのですけれども、建設費というのは、これくらいの規模のグループホームは、幾らぐらいのものが、今回、高騰で幾らになるのか。東京都の補助金と品川区の補助金があると思うのですけれども、その補助金の額も教えていただきたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"それから補助金の内訳ということですけれども、先ほど申し上げた建設費に対して、都の補助金が８,０００万円ほど、それから区の補助金が５,０００万円ほどということで、１億３,０００万円程度の補助金が支給されるグループホームとなっています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"先ほど利用者の募集も行っているということだったのですけれども、ここの対象というのは中重度者ということになっていたかと思うのですけれども、その点では、いつ頃から募集が始まって、今、どの辺まで来ているのか。ここは１０人の施設ということだったと思うのですけれども、何人くらいの応募があったのか。入居に当たっての入居者の選定の仕組みというのがどうなっているのか、伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"なので、まだ具体的な募集人員や応募があった状況ではございませんが、入居の選考に関しては、先ほど委員におっしゃっていただいたとおり、中重度というようなところで、こちらは公募の際にも。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、入居者募集というのはいつ頃から始まるのか。それから、入所の調整というのには区も関わっていくのか。調整指数というか、点数などはつけるのか、つけないのか。その点も伺いたいと思います。その点についても伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"職員の募集体制等につきましては、こちらも先ほどおっしゃっていただいたとおり、２ユニットで１０名の施設を想定しておりまして、それに対して、常勤・非常勤も合わせて１２名程度の職員を想定しているようなところで、そのうち法人内での異動等も当然ありますが。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"提案","question":"１６名に対して八十数名という状況だったと思うのですけれども、やはりグループホームは足りないので、希望する方もたくさんいらっしゃると思いますので、これから募集のやり方というか、入居者をどう決めていくのかというのは、事業者からの提案もあって、区と一緒に検討するということですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"ご説明ありがとうございました。これは３か月と書いてありますけれども、開始の時期については３か月。今年度から来年度になったということで、着工の時期がいつからどれぐらい遅れたのかということと、あとは、今年度から来年度になったことにおいて、何か予算など、今回は別に変更の議案というのはないのですけれども、例えば区の計画の中でどういう影響があるのか。その辺について教えてください。","respondent":"佐藤障害者施策推進課長","answer":"利用者におかれては、令和７年度中開設ということで見込んでいたところが、若干ではありますが遅れたというところで、利用を待たれていた方に関しては、個別には影響があるかもしれませんので、そういったところ、必要な部分についての支援は。","voiceIndex":13,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、業者が決まってから着工の時期が決まるからというお話があって、着工の時期はいつですかという質問をしたのですけれども、一、二か月ほど遅れたということで。別にいいのです。別に、了承と最初に申し上げましたけれども、議会に報告をするのだったら、その理由のところをしっかり、きちんと伝えていただかないと、議会への報告ということで私たちは伺っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。私の理解が不十分なところがあるかもしれないですけれども、それほど大きな工事ではないと、先ほどお伺いして感じたのですけれども、１,０００万円の増額で、調整に相当そんなに難航したのかなという新たな疑問もやはり生まれてしまいました。もう少し分かりやすいご説明を頂ければと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"つい、事業者の立場に立ってしまうと、こういうものの開設が延びると事業計画は相当狂うと思っていて、今日は開設が延びるという報告だけですけれども、結果としてそれは事業に影響してきて、それは今後、今、入居を考えておられる方のご希望がかなうかどうかにも影響してくるのかなと思うので、その辺については、事業者との話合いなどはしておられるのか。","respondent":"佐藤障害者施策推進課長","answer":"先ほどもございましたが、開設時期がずれるというところで、利用を考えていた方にとっては、そこに至った計画というか予定の部分がずれて、そこに対して、利用の支援やケアの部分については、必要になる方も個別にはいらっしゃるかもしれませんが、そういった部分については。","voiceIndex":20,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれご相談に乗ってというご答弁はありましたので、それは当然されるのだろうとは理解しておりますが、もう少し、個別の相談とともに、今日は議会への報告を受けておりますけれども、利用を想定されている方たちへの説明会などというのは行われないのでしょうか。ごめんなさい。今までのご説明にあったら、聞き漏らしたのかもしれませんけれども、その点をもう一度教えてください。","respondent":"佐藤障害者施策推進課長","answer":"利用者側への説明会というところにつきましては、開設に合わせて、こちらの見学等も含めた説明というのは行ってまいりますので、そういった形で、こちらの開設の周知も含めて、この内容そのものについての説明会というのはまだ行う予定はございませんが。","voiceIndex":22,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"この運営法人が、この事業ではなくて運営されているところは、大変誠実に対応はされているとは伺っておりますが、一方でやはり、失礼ながら、人材というのが十分にある法人ではないのではないかと、周辺の事情から考えているので、やはりこれを引き受けていただいてしっかり運営していただくためには、かなり区としても、補助になるのか、話合いというか、そういうことになるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点確認なのですけれども、開設時期が遅くなったということで、それに伴って、区から法人に対して何かしらのペナルティなどといったものはあったりするのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"ただ、貸付けは一応、期間を決めてやっている形になりまして、その部分については、それを遅らせるというようなところまでは想定しておりませんので、そこの契約期間に対する事業の一環というのは、若干ではありますが、そういった部分で影響が全くないとは言えない状況ですが。","voiceIndex":26,"id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"確認","question":"小山七丁目のグループホームのプロポーザルの実施要領に開設時期というのがありまして、ここに、令和７年度中に開設してくださいと書いてありまして、ぎりぎり言えば、令和８年３月３１日までなのかなというところで、それが遅くなってしまったというところで、一応、公募概要にはこういうふうに期限を定めてあるというところではありますけれども、遅れてしまったからといって、何かしらのことは、特に何も。","respondent":"佐藤障害者施策推進課長","answer":"おっしゃるとおり、事業者の公募の時点ではそういった形でさせていただいておりましたが、今回の理由に関しましては、社会情勢等に鑑みて、やむを得ない理由というところで考えておりまして、そこについては、特段の対応というのは予定しておりません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"質問","question":"続けてなのですが、貸付期間が３０年ということで、使用貸借の契約から３０年ということなので、そうなると、これは３か月ずれたことによって、契約期間の開始と終了はずれてくることはあるのでしょうか。教えてください。","respondent":"佐藤障害者施策推進課長","answer":"こちらの契約の開始期間については当初の想定どおりで進めてございまして、ずれた時期を鑑みまして、そこを変えるところまでの予定はしていないというところで、業者とも確認しています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"今回そういった、やむを得ない事情でということで、先ほどの、あくつ委員との質疑の中でも詳しくいろいろ事情をお伺いしたので、ある程度理解は進みましたけれども、やはり、こういった資材高騰を含めた延期ほか、最近で言うと元芝都営アパートの跡地の施設なども、物価高騰によって、決まった後で撤退してしまったなどといったことが、やはりいろいろ相次いで。","respondent":"佐藤障害者施策推進課長","answer":"それ以降、区の整備案件というようなところでは、グループホームについては今のところ出ているものはございませんが、出石つばさの家もそうですけれども、施設の内容や規模によっては、当然、区立案件というのも全くないというところではございませんが、一方で。","voiceIndex":32,"id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはり開設時期が遅れてしまうというのは、利用を希望されている方、区民の方にとっては機会損失にもなると思いますし、様々な計画というか予定も狂ってきてしまうと思いますので、ぜひその辺は慎重に検討していただいて、もし民設民営になった場合でも、しっかりと伴走していただいて、常にチェックといいますか、事業所の状況を聞きながら、もし何か不測の事態があれば、早めに動けるというか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"意見","question":"先ほど入居者の区分が４以上の方を５名以上受け入れるということで聞いているということだったのですけれども、中重度ということなので、支援区分の５や６の方がすごく入れないというのが、この間、議会にも陳情などがあったりもしていますけれども、区としては、５や６の重度者の方をここのグループホームに入居させてほしいというふうなことというのはどう考えられているのか。その点をお聞かせください。","respondent":"佐藤障害者施策推進課長","answer":"設備ですけれども、支援区分だけで、お体の状態などがどのような方が入られるかというところはなかなか難しいところがありますが、バリアフリー的な設備、スロープやエレベーター、それからリフト浴対応の居室等も設計ではしていると受けておりますので。","voiceIndex":36,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"意見","question":"品川区の場合、中重度という形で、いつも対象をそういうふうに言われていますけれども、世田谷区の計画を見ると、軽中度と重度ということで、グループホームがどれぐらい必要かという所要量を出して、それをどう整備していくかという計画にしているのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-017"}]},{"id":"topic-02","title":"品川区立障害児者総合支援施設の指定管理者候補者の選定","agenda":"品川区立障害児者総合支援施設の指定管理者候補者の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"３年間で替わったということも異例でしたし、これだけ利用者の方々から継続を求められていたにもかかわらず替わったというのも本当に異例だったと思うのですけれども、その中で４年半たって、様々、利用者の方の思いだったりというのがあると思うのですけれども、そういう中で、利用者や家族の方々のアンケートや、その当時、満足度調査というのもされて、その満足度調査の中でも、すばらしい。","respondent":"松山障害者支援課長","answer":"令和２年度に実施いたしました指定管理者の選定においては、設置目的を踏まえて、課題であった建物全体の管理を含めた総合的かつ一体的な施設の管理運営を行ってもらうために、異例ではありますが公募せざるを得なかったという実態がございまして、今回の場合につきましては。","voiceIndex":45,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その満足度調査というのは、前のときは情報公開でないと取れなかったのですけれども、それは公表されているのでしょうか。やはり情報公開でないと取れないという状況になっているのか、伺いたいのと、その当時、何というのですか、福栄会と、この指定を受けていたところと、満足度調査は両方ともされているのですけれども、すごく大きな差があったのです。その点も教えてください。","respondent":"松山障害者支援課長","answer":"利用者満足度調査についてです。品川区指定管理制度運用における実施要領によりますと、公表とすることとしているものというのが規定されております。満足度調査は特にこちらに規定されているものではございませんので、情報公開での対応ということになろうかと考えています。","voiceIndex":47,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"当然、今までもそうでしたし、この方針が改定される前は、そういった方針で、もう随意契約ではないですけれども、随意で指定管理が決まっていたということがあって、方針が改定になって一応５年ごとということになっていますが、やはり、この方針の改定によって緊張感が保たれるというか、この４年半は本当に頑張ってこられたことは私も認めますけれども、次、選ばれるのだということがないと。","respondent":"松山障害者支援課長","answer":"ただし、やはり委員がご指摘のとおり、そのまま何も変化せずに継続していくということではなくて、昨日の委員会でもご報告させていただきましたように、日中一時支援の環境整備や定員を増やそうということに努められたり、今後、児童発達支援センター。","voiceIndex":50,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"意見","question":"あと１０年間は可能性としては継続する可能性がある。ただ、やはり利用者にとってみれば、内容がよければ当然、継続性を持たせたほうが、利用者は障害の特性も様々あると思うのですけれども、やはり安定。だからこそ前回、かなりもめたということもあったのですけれども、そういうところですので、その点については、議会はじめ地域も含めて、しっかり見ていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"ご説明ありがとうございました。私も、特に福祉などという、特別という言い方はかえっていけないのかもしれないのですけれども、そういう対応が求められる施設について、あまり指定管理者がぐるぐる替わるよりは、安定したところでという考え方も、一定あると理解しております。一般質問等では取り上げましたけれども、眺めざるを得ない状況でした。ちょっと説明していただけたら。","respondent":"松山障害者支援課長","answer":"ただし、強度行動障害の方の行動特性によっては、やはりなかなか全ての方に合わせるというのは最初からは難しいので、その方の行動特性によって、ここは危険だということであれば、今も軽微なものについては、即、対応させていただいておりまして、そういった意味では。","voiceIndex":54,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、その方は結局、せっかく１人で行動できるのに、１人でトイレに入れない。それと、ユニバーサルベッドがついているのですけれども、このユニバーサルベッドの角度で、どうやって車椅子を止めたらいいのだというのも、私は叱られました。だから、そういう不具合というのは、作ってみて初めて分かるところもあるではないですか。それで、今指摘したのは直っていますかというのも、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"設備についてですが、やはりベーシックなしつらえや、あるいは、おっしゃられるような個別のことにつきましては、対応できるものは区と一緒になって対応していますし、例えば現指定管理者が、非常にここが使いにくいといったものにつきましては、またご提案を頂いて。","voiceIndex":56,"id":"exchange-023"},{"speaker":"吉田委員","kind":"確認","question":"避難についても、エレベーターが使えるか使えないかなど、非常用電源は別に確保されているエレベーターだと確認したのですけれども、結局、避難のときには使えないということも分かりましたし、ぐるっぽ自体、建物自体の問題ですので、指定管理者の責任の範囲ではないかもしれないですけれども、運営に当たっては、避難をどうするかなどということは、そういう不具合が運営に影響してきてしまうと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-024"}]},{"id":"topic-03","title":"発達障害・思春期サポート事業","agenda":"発達障害・思春期サポート事業","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"パルレの発達障害・思春期サポート事業ということで、「ら・るーと」ですよね。この事業を行って、どれぐらいたつのか。何年前ぐらいからされている事業なのか。それと、この事業に対しての区の評価はどういう評価だったのか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"事業者からもございましたように、本当に事業開始当初と比較して支援体制が充実してきたということで、一定の役割を果たしてきたということで、ご自分たちもそのように思っておりますし、区としましても、発達障害に特化したところとして、この事業を評価してまいりましたので。","voiceIndex":66,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私たちも、毎年、どんな思いでされているのか、どんな状況なのかということで、障害者団体の皆さんと懇談させていただいていますけれども、パルレともずっと懇談させていただいて、本当に熱心な質の高いサービスをしていただいているのだなという、何というのですか、熱い思いをいつも感じさせていただいていたところなので、こういう報告があるというのは、ちょっとショックというか。","respondent":"松山障害者支援課長","answer":"同じ講師の方で、同じようなスキームで実施しておりますので、ペアレントトレーニングにつきましては児童発達支援センターで、普及啓発につきましても大原児童発達支援センターもできましたので、２か所の児童発達支援センター、あるいは発達障害者支援施設でも、各センターごと。","voiceIndex":68,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"歴史もあって、かなり、親の面談が毎月８５件もあるというのは、すごくパルレが頼りにされているというところがこういう件数にもなっているのではないかと思うのですけれども、パルレから伺ったのは、赤字のために、区独自の事業なので、全面的に区の財政で受託しているということになると思うのですけれども、それが赤字なのでやっていけないということで。","respondent":"松山障害者支援課長","answer":"今回、パルレからの申し出の中に、別に実施する計画相談事業所に注力したいためです。もともとパルレは、計画相談事業所が別にもう既にありまして、それは区の補助もきちんと、ほかの計画相談事業所と同様に補助金を出しております。","voiceIndex":70,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、実績のある豊かな本当に熱心なところは、赤字というのは、支援を増やしてもらいたいというのは、毎回、毎年伺っていたところだったのですけれども、そういう点では状況もじっくりと聞いていただいて、区としてもできる支援をしていただいて、事業所を継続できるように、ぜひともしていただきたいという思いがしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"吉田委員","kind":"確認","question":"今後は、でも計画相談事業所としては残るわけですから、その前の、計画相談に至る前の相談というのを、パルレには結局のところ、続けていただけるのではないかと、私は期待しているのですけれども、その辺の事業継続についての今後の区との関係というものについては、今後の問題として話合いが進んでおられるのかどうか、確認させてください。","respondent":"松山障害者支援課長","answer":"やはり、委員ご指摘の、計画相談の前の基本相談については、国は報酬が全くないので、なかなか計画相談事業所として継続は難しいということで、区としては平成３１年度から、既に独自で助成をしていますので、熱い思いを持った。","voiceIndex":74,"id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"質問","question":"恐らく年間２,７００万円ぐらいの補助は入れていらっしゃると思うのですけれども、恐らくですけれども、やはり赤字で撤退ということを考えると、これは福祉事業のジレンマですけれども、熱心にサービスを提供しようと思って手厚くすればするほど、手間がかかって、人件費もかかって、そして赤字になってしまって、苦しくなってしまうという、その一例が起きてしまったのではないかとは考えておりますが。","respondent":"松山障害者支援課長","answer":"私どもが伺っておりますのは、赤字で撤退ということではなくて、９月にやはり、ご説明した申し出がございまして、支援体制が充実して、一定の役割を果たしたこと、障害児通所支援の利用増加に伴って計画相談が増加傾向にありますので。","voiceIndex":77,"id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"パルレからの説明は違ったということだったのですけれども、やはり様々な可能性、実はこんなことなのではないですかというようなことを聞くぐらいは、１６年以上、品川区で運営されて、信頼関係もある事業所ですから、その辺はもう少し丁寧に聞いていただいて、それこそ、いわゆる伴走するという形を取っていただくべきだったのではないのかと思ったりして、だから、言葉だけをうのみにせずにというか。","respondent":"松山障害者支援課長","answer":"その後ですけれども、パルレの従業者につきましては、パルレの法人のことですからということを受けまして、現時点では従業者の方はパルレの従業者の方ですので、パルレの代表の方からは、それ以上の話はございませんでしたし、私どもも。","voiceIndex":79,"id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。３月までは事業がまだあるということで、４月以降に関しては、パルレの今お仕事をされている方というのは、そのままパルレの中で別の事業に移ったりという可能性が一応あるから、今後撤退する事業で今働いている職員の方に対してどうのこうのは、新しい、げんきに行ってくださいなどということは特に言えないということだと受け止めてよろしいですか。","respondent":"松山障害者支援課長","answer":"パルレの従業者のことは内部のご事情に当たりますので、そこまでご説明を区には頂いておりませんが、それぞれ、パルレの代表の方、従業者の方とお話しして決めることであると、区としては思っております。","voiceIndex":81,"id":"exchange-032"}]},{"id":"topic-04","title":"令和８・９年度後期高齢者医療制度保険料率の改定（算定案）","agenda":"令和８・９年度後期高齢者医療制度保険料率の改定（算定案）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"２０２２年１０月に制度改定されて、現役並みと言われる、所得に準ずる、一定以上の所得の人の窓口負担が１割から２割になるということが、今年の９月３０日までは外来窓口が１か月３,０００円までという措置のことでいいのでしょうか。このマイナス７２億円というのは、その分、高齢者の自己負担が増えるということになるのだと思うのですけれども、その点もひとつ教えていただきたいと思います。","respondent":"山下国保医療年金課長","answer":"幾つかご質問いただきましたけれども、まず配慮措置の終了に係る、委員からのご指摘のところですけれども、ご説明については、委員がおっしゃられたとおりでございまして、本年９月まで、２割負担の方については上限３,０００円ということで行われていたものについては。","voiceIndex":88,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問","question":"これをもっと引き下げられないのかという思いがしているのですけれども、その辺のところはどう考えられているのか伺いたいのと、今回、子ども子育て支援分というのを後期高齢者にも負担させるのかという、本当にそういう問題はあると思うのですけれども、それも含めて、平均で１万２,４７１円、１１.２％もの値上げということになるわけです。","respondent":"山下国保医療年金課長","answer":"皆様で令和８年４月１日からご負担いただく、お支払いいただくようなものになります。最後にございました、後期高齢者医療保険料の上昇の率というところですけれども、今回、先ほど冒頭ご説明申し上げましたように、１１.２％の増というところでした。","voiceIndex":90,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"こんな物価高のときだからこそ、財政安定化基金拠出金はゼロということではなくて、これを区からも出して、そしてもっと基金の中から、今回４２３億円ということですけれども、これは東京都全体での額ですから、品川区に合わせるとどれぐらいになるのか分からないですけれども、これをもっと増やして、幾ら何でも、１１.２％の１万２,０００円を超える値上げというのは本当に厳しい状況なので。","respondent":"山下国保医療年金課長","answer":"先ほど委員からは、下げる要素としてというところがございましたけれども、別紙の右側に記載があります保険料算定の変動要因としましては、診療報酬の改定や、その他、税制の改正等の影響ということで、それが増える要因、減る要因、それぞれ様々あろうかと思うのですけれども。","voiceIndex":92,"id":"exchange-035"},{"speaker":"鈴木委員","kind":"意見","question":"本当に、国の税金の使い方ということに根本的になってくるのだろうと私は思いますけれども、今、病院なども、もう６割が赤字で、自治体病院は９割が赤字と言われて、本当に医療の現場で働く人たちも賃金が上がらずに大変な状況の中で、やはり診療報酬の引上げというのは、どうしても必要なのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-036"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"今回は「高齢者とデジタル社会について」というテーマで、社会参加促進と介護予防への活用ということでのテーマだったと思うのですけれども、今ご報告があったのは、高齢者のスマホと、みんチャレアプリというところの課題に対しての品川区の取組ということなのですけれども、テーマが大きかったのかどうかというところで、１点だけご説明があったのですが、これだけでいいのかというところで。","respondent":"樫村高齢者地域支援課長","answer":"今回、テーマとして取り上げたというのが、先ほど委員がご指摘のとおり、高齢者のスマホ保持率と、それから介護予防における社会参加の重要性に着目しまして、今年度から実施しております、みんチャレアプリで。","voiceIndex":101,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"なぜかというと、今回行政視察で、まさに愛知県のそういうものを、まさに今おっしゃっていた「はじめてのスマホ教室」のようなものでの、ちょっとまたやり方が違うのですけれども、そういったものを視察してまいりましたので、そのことも今日伺おうかと思っていたのですが、みんチャレアプリというところだけだと話が広がらないなと思って、少し気になったので質問させていただきました。","respondent":"樫村高齢者地域支援課長","answer":"そちらは、スマホ体験教室と連動しまして、分からないところでも、その他のところでもいいのですけれども、引き続き午後にご相談を受け付けるような体制となっておりまして、そこではそういった、例えばＬＩＮＥの使い方や、そもそもダウンロードしたいなどというご要望があれば。","voiceIndex":103,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"例えばａｕやドコモなどのキャリアの方が協力してやっていただいているのかというところ、キャリアのメーカーなのか、それとも誰がやられているのかということをまずお聞きしたいということと、やはりそういった高齢者の方のデジタルのニーズというのは、ここにも利用率の乖離というデータはあるのですけれども、何を求められているのかというところです。","respondent":"樫村高齢者地域支援課長","answer":"どの辺が区民ニーズが高いかといったところですが、今、細かい資料を持ち合わせていないのですが、スマホよろず相談の中でもアンケートなど分析を取っておりまして、ＬＩＮＥのご相談というのが圧倒的に多いというのが、データとして統計が取れています。","voiceIndex":105,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"別の意味での社会参加というところで、そういったニーズをつかんでのデジタルサポート的なものも、ぜひお願いしたいと思いますけれども、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"現在も先ほど申し上げておりましたとおり、スマホ教室やスマホよろず相談等で、きちんとアンケートを取ったり、それからどういったご質問が多いかなどというような分析はきちんと取りますので、ニーズに合わせた展開というのを引き続きしてまいりたいと考えています。","voiceIndex":107,"id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どういう形で取組がされているのか、地域ごとにやっているなど、どんな形でやっていて、実績がどれくらいあるのかというのを教えていただきたいのと、みんチャレアプリのところも、健康になるスマホアプリ教室ということなのですけれども、ここで実績が、４教室で参加９３人ということなのですけれども、これも品川区全体を対象にして、どういう形で呼びかけて。","respondent":"樫村高齢者地域支援課長","answer":"２点お尋ねいただきました。「はじめてのスマホ教室」ですけれども、まず会場としましては５会場で実施しておりまして、それぞれ教室は、枠が狭いのでそんなに人数はないのですけれども、今年度は延べ３２０名の定員でやる予定になってあります。","voiceIndex":110,"id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"それと、もう本当に、スマホが電話をかけるだけという人も、すごく周りにも結構いるなという思いはしているのですけれども、そういうときに、さっき申し上げたように、例えば高齢者クラブなどでスマホ教室をやりたいなどといったら、アライ電機産業ですか、そういうところで派遣してもらえるみたいな仕組みというのはあるのか、その点も教えてください。","respondent":"樫村高齢者地域支援課長","answer":"２点ご質問を頂きました。最初に５人１組でという話で、最大５人でというところで、このアプリが複数人でやるアプリになりますので、一応このアプリは２人から５人までというような形で、その方々の状況に応じて、２人から５人で選んでいただくような形になってあります。","voiceIndex":112,"id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問・要望","question":"スマホ教室というのは、どこでも結構人気でというのを聞いて、世田谷区に地域包括支援センターのことで話を聞きに行ったときも、結構、地域包括支援センターごとにスマホ教室をやっていて、結構それがすごく要望がたくさんあるというのを伺ったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-043"},{"speaker":"大倉委員","kind":"質問","question":"みんチャレアプリのグループが２１グループということで、どんなテーマのグループになっているのかなどというところは把握しているのでしょうかというところで、もし把握しているのだったら、どんなテーマのグループがいらっしゃるのかというのを教えてください。","respondent":"樫村高齢者地域支援課長","answer":"このグループのテーマなどは特に決めていないので、仲のいい方で組まれている方もいらっしゃいますし、教室の中で知り合った方と組まれている方というのもいらっしゃるということで、多岐にわたると認識しています。","voiceIndex":116,"id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。みんチャレアプリを見ると、散歩グループ、読書グループみたいな、禁煙、節酒などと書いてあったりして、そういうテーマを持ってやっているということではないということなのかなと、今のご説明だと思ったのですけれども、もう一回、その辺を教えていただければと思います。","respondent":"樫村高齢者地域支援課長","answer":"なので、運動をすごく頑張ろうということで歩数なども高めにするグループもありますし、本当に健康で、緩く長く続けていきたいねというときには、話合いをして歩数の目標値をなるべく低めに設定してなどという形でやっているところでございまして。","voiceIndex":118,"id":"exchange-045"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、テーマなど、ある程度、今は持っていないけれども大体把握されているということでいいのかというのと、やはり今のお話を聞くと、社会参加や地域活動などというところにどうつなげていくのかというのが課題なのかなと思っているのですけれども、その辺はどういうふうにつなげていく、もうこれがつながっているということなのかどうか、またもう少し先に。","respondent":"樫村高齢者地域支援課長","answer":"さらに今後、みんチャレアプリがあってもなくてもということで、やりながらでもいいのですけれども、地域貢献活動につなげていただきたいというところで、区から、みんチャレアプリを通じて情報発信等もできますので、ボランティア情報の発信や、また。","voiceIndex":120,"id":"exchange-046"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。それでいうと、例えば、調べるとポイントなどがあって、何かもらえたりみたいなのも、資料では載っていなかったですけれども、みんチャレアプリを見るとそういうメリットがあったりするのですけれども、そういうポイントなどというのは考えていたりされているのか、やっているのかも含めて教えていただければと思います。","respondent":"樫村高齢者地域支援課長","answer":"まだ品川区では実現できていないのですが、みんチャレアプリとしましては、寄附制度がありまして、協賛いただいた企業に対して、歩くとポイントがたまる制度になっていまして、それを、みんチャレアプリに参加している方が、自分が歩いたことによって取得したコインを。","voiceIndex":122,"id":"exchange-047"},{"speaker":"大倉委員","kind":"意見","question":"台東区などで、そういうのを既にやって、寄附プロジェクトみたいなものでやられているというのも見させてもらっていまして、そういうのが社会に、自分たちが歩いたポイントが、例えば台東区でいうと、子どもたちにサッカーボールを寄附して、遊んでいる姿を見てもらうみたいな感じなのかなというところがあったりするので、そうすると、また参加したことで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、具体的に、ここの子ども食堂と関係が深いという方には、そこにお手伝いができることはあるかと声をかけてくださる高齢者もいらっしゃるのですけれども、そういう関係がなくても、興味があるという方もいらっしゃると思うので、そういう方たちの思いを実現してあげるみたいな仕組みができたらいいなと思うのですけれども、今後の展望になると思うのですが、その点についてはいかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"先ほど申し上げました表彰式等々も今後考えているところですので、そういったところでの、こういった事業がありますよというところの周知もできると思いますので、社会福祉協議会とも、連携の上でにはなると思いますけれども。","voiceIndex":126,"id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"せっかくの仕組みですので、その発展形ということも、ぜひ今後検討していただけたらと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"確認","question":"すみません。そもそもの確認なのですけれども、「みんチャレ」というのは何の略で、正式名称は何でしょうか。","respondent":"樫村高齢者地域支援課長","answer":"すみません。恐らくになるのですけれども、「みんなでチャレンジ」だと。今、資料を持ってきたのですが、正式な名称はたしか、「みんなでチャレンジ」だったと認識しています。","voiceIndex":130,"id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"確認","question":"それで、これは確認ですけれども、今回の、みんチャレというのが、一応、デジタルデバイド対策にもなっているということで、みんチャレの機能を見ると、恐らくＬＩＮＥを使う、疑似ＬＩＮＥというか、ＬＩＮＥの機能的なものに似ている、類似しているのかなと思うので、お考えとしては、ＬＩＮＥに慣れてもらうみたいな、その導入みたいなお考えなのでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"ＬＩＮＥと違うところとしては、チャット機能や写真を送るのなどは同じなのですけれども、歩数がみんチャレアプリと連動して自動的に集計されるというところと、１日１回、必ず歩数を投稿することになっているのですが、歩数を送るときに、勝手に歩数が行くのではなくて。","voiceIndex":132,"id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、ＬＩＮＥに慣れてもらうためというよりは、どちらかというと、ＬＩＮＥを利用している高齢者の方が取っつきやすい仕様だから、ふだんＬＩＮＥを利用されている方だと、みんチャレにすんなり入りやすいなどというところもあるのでしょうか。いかがでしょう。","respondent":"樫村高齢者地域支援課長","answer":"一応、そういったところも想定はしておりまして、そこも含めて考えたところです。","voiceIndex":134,"id":"exchange-053"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そうなると、何というか、みんチャレというのは当然、運動や社会参加、区から通知があったりという、非常にいい要素があるのですけれども、あまりデジタルデバイド的な要素は、そんなに比重としては、区としては低いというか、そういったお考えでよろしいですか。","respondent":"樫村高齢者地域支援課長","answer":"あくまでデジタルデバイドの解消のためにこの事業をやっているというわけではないのですけれども、これをやることによって、それにも効果があるとは考えてあります。","voiceIndex":136,"id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"実際は、これは今、都議会の第４回定例会にかけられている補正予算で実現する話なので、その１万ポイントはまだスタートしていないのです。ちょっと取り留めのない質問になってしまいましたけれども、何となくニュアンスは伝わったのかなと思いますので、その辺り、介護予防というところに特化せずに、デジタルデバイド対策もぜひやっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"高齢者地域支援課だけの範疇にとらわれずに、そういったところをチャンスとして捉えまして、所管課とも連携しながら、現在も区内共通デジタル商品券の使い方につきましても、所管課と連携して説明をスマホ教室の内容に一緒に盛り込んで行うような対応を行っていますので。","voiceIndex":139,"id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点だけ聞き忘れてしまったので確認です。６０日間継続率８３％というのは非常に高いなと思ったりするのですけれども、みんチャレアプリというのは他の自治体も実施しているそうなのですが、もし分かればでいいのですが、他自治体の６０日間の継続率などという数字が、もし分かれば。","respondent":"樫村高齢者地域支援課長","answer":"委員ご指摘のとおり、みんチャレアプリにつきましては他の自治体でも実施しておりまして、委託業者の資料によりますと、他自治体につきましては、６０日間で７５％の継続率ですので、品川区の継続率は、これと比較すると高いのかなと認識しています。","voiceIndex":142,"id":"exchange-056"},{"speaker":"えのした副委員長","kind":"質問","question":"私からも１点、今の継続率が非常に高いなと思って、やはりこういった事業は継続していくことが大切だと考えています。そういったものを、例えばＡＩなのか、そこに区の誰か担当が入るというのは無理ですけれども、ここ１週間、このグループは動きがないなというときに、「最近活動されていませんけれども、暖かくなったので動きませんか」などといった機能というのは、あるのかないのかというのを伺いたい。","respondent":"樫村高齢者地域支援課長","answer":"私の説明不足で申し訳なかったのですが、このアプリにつきましては、１組最大５人で結成して、チーム内で活動していくと、歩数を投稿するとかしないとか、あると思うのですが、設定したＡＩのキャラクターというのが設定されておりまして、それもチームで決めたときに、結構。","voiceIndex":146,"id":"exchange-057"},{"speaker":"えのした副委員長","kind":"意見","question":"そんなアプリのＡＩキャラクターについて、さらに認識いたしました。私もやはり何歩以上歩いたときに、ＡＩであっても「おめでとう」みたいな言葉をもらえると、またさらに続けようかなという気持ちになるので、そういった機能を活かして続けていけるようなサポートをぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-058"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"委員長に言っていただいたとおりなのですけれども、あくつ議員の質問の中で、介護保険のサービス利用者に対して、負担軽減に資する時限的な措置を行うという答弁があったと思うのですけれども、それが具体的にどのようなことなのかを伺いたいというのが１点です。","respondent":"菅野高齢者福祉課長","answer":"とはいえ、現下の災害級とも言える物価高騰により、本来利用すべき介護サービスの利用を控えざるを得ないといった事態はあってはならないと考えており、法律や制度上の課題を解消した上で、物価高騰に対応した措置として。","voiceIndex":152,"id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問","question":"サービス利用者の負担軽減ということは、サービス利用料というのが基本１割で、所得に合わせて３割というのもあると思うのですけれども、その利用料の負担を減らすという考え方でいくということなのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"先ほども申し上げましたが、利用者の負担割合というのが、国が定めているという場合もありますし、他の自治体などでも、この負担割合を少し減額している例もあるのですが、低所得者に対する負担割合の軽減などといった形で。","voiceIndex":154,"id":"exchange-060"},{"speaker":"鈴木委員","kind":"意見","question":"これは、具体的なところはこれからということになるので、中身としては、それ以上、なかなか具体的なところというのは難しいのかなと思うのですけれども、利用料というのは基本１割のところから、もうだんだん所得に合わせて３割負担などというところが出てきてしまった部分があると思うのですけれども、そこのところを、自治体によっては、低所得者は１割ではなくて５％の利用料などと。","respondent":"菅野高齢者福祉課長","answer":"これは、介護保険制度が始まって以来、幾つかの自治体でそういう展開があるとは認識しているのですが、今回、区で話をしているベーシックサービスということが、皆に等しく一律にというようなところも方針としてありますので。","voiceIndex":156,"id":"exchange-061"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことで、例えば介護保険が始まった当時、保険料の減免などにしても、たしか、記憶が曖昧なのですけれども、千葉県のどこかの地域で、自治体で保険料の減免というのを、一般財源を入れてやっていたところが１か所あったような気がして、その当時はそういうところもやっているので、品川区でもやってほしいというようなことも要望した記憶があるのですけれども、そういうときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"来月から制度を運用していくというような答弁だったかと思うのですけれども、具体的にどうなっていくのかということで、外国人の滞納の状況や理由なども含めてご説明いただきたいということで、お願いしたいと思います。","respondent":"山下国保医療年金課長","answer":"引き続き、国民健康保険に加入しているの皆様に、国民健康保険制度を正しく理解いただき、保険料を納付していただけるよう、作成しております４か国語の多言語パンフレットの活用や窓口での丁寧な説明に努めていくほか、国籍を問わず。","voiceIndex":161,"id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問","question":"今のは、いま一つよく分からなかったのですが、１年以上、未納の外国人の方を、出入国在留管理局に区から知らせて、出入国在留管理局から区役所に来庁するようにということを勧めてもらう制度ということですか。そこをもう一回お願いしたいと思います。それから、外国人の収納率というのは７７.１３％。品川区に在住されている外国人の中で何％ぐらいなのかというのも教えていただけたらと思います。","respondent":"山下国保医療年金課長","answer":"制度の仕組みの部分です。先ほど委員がおっしゃられたようなところが基本的な流れになるのですが、もう一度改めてご説明申し上げますと、区から出入国在留管理局に情報提供します。","voiceIndex":163,"id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうしますと、外国人の国民健康保険の加入率というのは８％ということで、たしか、一般的に、品川区全体でいえば、国民健康保険の加入者というのは１５％ぐらいかと思うのですけれども、一般的に品川区全体の国民健康保険加入者に比べたら、外国人の国民健康保険加入者というのは、約半分近くの少ない割合ということで考えていいのでしょうか。","respondent":"山下国保医療年金課長","answer":"区における納付相談の体制ということですけれども、基本的には区の相談窓口である整理係で受付をしているところでございまして、やはり言語の上で壁があるというところについては、多言語で伝えるタブレット、通訳タブレットというものを用いて、都度。","voiceIndex":165,"id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問","question":"外国の方の、何というのですか、もともと国民健康保険というのは社会保険ではない方が入るので、非正規の人などが多いと思うのですけれども、そういうところで、結構、転職だったり転居だったりというものの頻度が高かったり、そういうところで制度の理解や手続を失念したり、それから払うのが遅れてしまったりということが生じやすいというベースがあるということも報道されているところなのですけれども。","respondent":"山下国保医療年金課長","answer":"実際に未納が生じる前にやはり納付していただくことが一番肝要かと考えておりまして、納付のご案内時期等をお知らせするものについては、今は２言語ですけれども、日本語表記と英語表記ということでお示ししておりまして。","voiceIndex":167,"id":"exchange-066"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところに、何というのですか、「ビザがもらえなくなるよ」という、脅しみたいな形ではなくて、もっと外国の方が滞納に陥ってしまったような状況というのを区としてもしっかりと把握して、そこに寄り添った対応というのが求められるのではないかと思うのですけれども、その点はどうなのかということと、それから外国の方が滞納する理由というのは区として把握されているのか。","respondent":"山下国保医療年金課長","answer":"未納に至る理由というようなところについては、事前に納付の相談に来ていただければ、どういったご事情でということを事細かに聞き取り、生活状況などもお伺いすることができますけれども、窓口においでいただけない。","voiceIndex":169,"id":"exchange-067"},{"speaker":"鈴木委員","kind":"質問・要望","question":"一般的に通知を出して１年間滞納、それで出入国在留管理局を使って、「ビザがなくなるかもしれないよ」ということで来庁させるというやり方というのは、私はぜひとも慎重にしていただきたいと思うのですけれども、いかがでしょうか。それと、１年以上過ぎた未納者というのがどれくらいいらっしゃるのかということも教えていただけたらと思います。","respondent":"山下国保医療年金課長","answer":"実際に、様々な状況がある中で未納になっていらっしゃる方について、寄り添った対応に努めている中で、生活状況等を伺いながら、実際の保険料の納付につなげていただくような納付相談というのを行っておりますので、委員がおっしゃっているところの納付相談は。","voiceIndex":171,"id":"exchange-068"},{"speaker":"鈴木委員","kind":"意見","question":"外国人だから、日本人だからというところで、外国人だから出入国在留管理局を使ってというところで、これからすごく厳しく、国としては対応していくということですけれども、そこのところは、ぜひとも慎重にしていただいて、本当に外国人の方でも、払いたくても払えないという状況というのもあるのではないかと私は思いますし、そこのところは、慎重な対応と親身な対応ということを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":173,"id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問","question":"外国人の方の未納ということなのですけれども、これは、該当する外国人という方の中で、私が想定する中で、例えば外国人の方で日本人の方とご結婚されてお子さんが生まれたりして、離婚されて日本にお住まいになっていて、社会保険に入れるほど就労できていなくて、それで子育てもあったりして、かなり貧困というか、生活が苦しくて未納になっているみたいな方も想定されるかと思うのですけれども。","respondent":"山下国保医療年金課長","answer":"今、委員がご紹介になられた、いわゆる離婚されてということで、世帯が分かれていくという中で、別れられた外国人の方が世帯主になられているのであれば、数には含まれてくるものと考えます。","voiceIndex":175,"id":"exchange-070"},{"speaker":"やなぎさわ委員","kind":"質問","question":"大分、範囲が広くなると、もしかしたら紹介し切れないかもしれないですけれども、この中で国民健康保険に加入している外国人の方というのは、それ以外で大体どういった方が一般的に想定されるのでしょうか。もしご紹介できれば、国民健康保険に加入している外国の方の属性といいますか。","respondent":"山下国保医療年金課長","answer":"属性ということで申し上げますと、なかなか属性というのを表現し難いところがあるのですが、在留資格というところで申し上げますと、やはり留学で来日されて、国民健康保険に加入されていらっしゃる方が一番多いようには把握しています。","voiceIndex":177,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"意見","question":"この件については個別に問合せ等もさせていただいたので、気にはしていたのですけれども、ああいう報道があって、ただ自治体でというのが、対象となっている期間が非常に、その間、例えば品川区で受給していた方がどういう状況にあるのか、お亡くなりになっている方もいるしという中で、今、率直な感想として、自治体はもう国に、自治体でやるのはやめてほしいということを。","respondent":"豊嶋生活福祉課長","answer":"それで、遺族がいてもそれは支払いから外しなさいということは、今、「案」の状態では書かれています。中には、継続している方であれば、我々は今データを持っていますが、やはり５年間保存という規定がありますので、今、データがすぐ手元にない方もいます。","voiceIndex":188,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。ただ、私どもの立場とすれば当然、権利がある方には追加給付をしていただきたいという立場ですから、本当にご苦労をおかけしますけれども、そこはぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7227#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":62455,"voices":196}},{"id":"r07-20251126-8","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"建設委員会","time":"午前１０時１１分～午後 ０時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「品川区中高層建築物等の建設に関する開発環境指導要綱」等の改正","agenda":"「品川区中高層建築物等の建設に関する開発環境指導要綱」等の改正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の改正に当たって参考にしたひな形ですとか、他区の例などはあったのかというのを伺いたいと思います。内容について、地域では、結構インバウンドというか、宿泊者等を対象にした、規模が決して小さくない、民泊なのか旅館業なのか、そういうビルが増えているのですけれども、それらは今回の要綱改正の対象に入るのか、それとも既に対象になっているのか教えてください。","respondent":"高梨都市計画課長","answer":"最初に、参考にした内容ですけれども、調査・検討の委託もさせていただきまして、他区や他自治体の事例、また、日々、窓口等で事業者等と協議する中でいただいているご意見等も参考にしながら、今回、改正内容についてまとめてきたところです。半年間の周知です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。そういった話も伺っています。もう少し併せて内容について伺います。今回、寄宿舎と書いているのは、少し古めかしい用語だと思うのですが、最近区内でも増えているこの寄宿舎、相談が増えているという話もありましたけれども、建て主はどういうところで、どのような用途で、どのような方々が住んでいるところが多いと区は把握しているのか、伺いたいと思います。","respondent":"高梨都市計画課長","answer":"規模要件に該当すれば、寄宿舎についても適用という形になります。民泊についてのお困り事というのは、地域から声も寄せられているところですので、民泊に関する指導を所管している保健所等とも連携をして、地域の声に応えてまいりたいと考えています。寄宿舎の最近の動向です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。管理人がいない、今まではなかなかそういうルールがなかった。それで、少し伺いたいのですが、管理人規定の内容について、厳しくした点と緩くした点があると思うのですけれども、それをもう少しご説明いただきたいと思います。キッズルーム等の基準変更というのはどういう内容なのか、もう一度、すみません、ご説明いただければと思います。","respondent":"高梨都市計画課長","answer":"ただ、冒頭申しましたとおり、やはりごみ出しについての陳情が多いという状況がありますので、燃えるごみの収集日は朝来てくださいねといったことも、建物の規模に合わせて柔軟に対応してまいりたいと考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。最後に、この内容とは直接関わらないのですが、１点お伺いしたいのが、駐車場ですとか駐輪場の設置義務についてです。今回、検討課題の俎上には上らなかったのか、伺いたいと思います。２点目、これはすぐ改定してほしいと思います。解体説明会の案内の対象にぜひ私道の所有者を入れていただきたいと思うのですが、いかがでしょうか。","respondent":"高梨都市計画課長、川原住宅課長","answer":"これから要綱の改正作業に入ってまいりますけれども、今いただいたご意見を参考にして、楽なほうへの選択が進まないような形で、何か工夫できるか、しっかりと考えてまいりたいと考えています。２点目、駐車場についてです。そういったところで、引き続き丁寧な対応をしていくとともに、私道の持ち主に関しての周知というところは、ご意見として研究させていただきたいと思います。","voiceIndex":13,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"指導要綱の改正ということで、幾つか伺いたいと思います。この規制がどこまで実効性があるのか、そこを伺いたいと思います。どんな相談なのか、どんな困り事の声が寄せられているのか、伺いたいと思います。主流なのでしょうか、２０部屋以上は。そこがよく分からないので伺います。３点目、それにも関わるのですが、２０部屋以上とした根拠を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"簡単に申しますと、ファミリータイプの住戸については、１室当たり１.５台以上、もう少し面積の狭いものについては１室当たり１台、ワンルームタイプ等であれば１室につき０.５台という形で換算をして、その集合住宅に必要な駐輪台数について、要綱の中で設定しています。","voiceIndex":18,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"２０部屋以上あるところということでした。その場合、対象にはならないけれども、近隣の方からご相談があった場合には、どのように事業者と調整するのか、打合せするのかという点を伺いたいと思います。設置の台数はもっと増やしたほうが現実的かと思うのですが、その点も伺います。努力義務なのか、求めるだけなのか、それとも義務なのか、そこを確認させてください。それとも週２とかですか。","respondent":"高梨都市計画課長","answer":"今回の改正では、現行の駐輪場の台数で考えてはありますけれども、また駐輪需要といったところも、社会情勢の変化等も踏まえて変わってくるものであるという認識ですので、引き続きそういった状況を注視するとともに、また利用者の動向等、事業者等からもお話を聞くなど。","voiceIndex":20,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう少し、５０平方メートルより５５平方メートルとか、４人家族だったらやはり６０平方メートルだとか、なかなか一概には言えないところですけれども、今回、４０平方メートルから５０平方メートルに上げたということなので、それはそれでよいのですけれども、ファミリータイプというのであればさらに大きくしていくという検討状況、その辺はどういう規模だったのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"他区の状況を見ても、４０平方メートルとしているところが多くありますが、今回、そこからのさらにもう一歩といったところで、他区の事例等も見て、５０平方メートルを設定させていただいたという状況です。","voiceIndex":22,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほど、寄宿舎が区内にどれだけあるか分からないが、相談件数が増えているというお話があったと思います。宅配ボックスの設置については、指導対象がどのぐらい増えると見ているのか、お聞きできればと思います。","respondent":"高梨都市計画課長","answer":"今回の緩和によって、対象件数がそんなに大きく増減することはないかなと思ってあります。宅配ボックスについては、ほとんどの集合住宅が対象となり得ると考えていますので、年間そのぐらいの、７０件程度が要綱対象となるのではないかです。","voiceIndex":25,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"確認","question":"要綱ですので、先ほどの議論の中にも努力義務的な基準、手続になる、物理的な拘束力というのは、というお話もあったと思います。後からできた要綱によって指導の対象となるので、宅配ボックス事業が環境課で行われていると思うのですが、そこを手厚くしたり、考慮したりされるのか、そこだけを確認でお聞きできればと思います。","respondent":"高梨都市計画課長","answer":"一定規模以上、それなりの規模の集合住宅については、要綱でしっかりと設置義務というか、お願いベースにはなりますけれども、事業者でしっかり設置してくださいねといったところで進めてまいりたいと考えています。","voiceIndex":27,"id":"exchange-009"},{"speaker":"せお副委員長","kind":"質問","question":"５年に１回の見直しということだったのですが、どういった方たちで検討されてこういうふうになっているのか。これは決めるに当たって、何か会議体があるのか。を教えていただけますでしょうか。","respondent":"高梨都市計画課長","answer":"今回、要綱という位置づけもありますので、今回の見直しにつきましては、我々区のほうで専門会社に調査・検討委託を行い、他区の事例であるとか、あと一般的に全国的な状況等も踏まえて検討して、今回、改正をしていくところです。","voiceIndex":30,"id":"exchange-010"},{"speaker":"せお副委員長","kind":"質問・要望","question":"実際に品川区に住んでいる方たちにも意見を聞いてほしかったなと、正直そういう思いがありましたので、そういった機会も捉えながら、次は５年後になりますが、進めていただきたいと、そこは要望します。５０平米以上にして、こういった要綱を整えて、事業者も大変だと思いますが、今って、例えば５５平米で品川区内だともう１億円を超えたりするではないですか。","respondent":"高梨都市計画課長","answer":"今ご指摘のありました、とはいえ、やはりなかなか手が出しづらいというところについては、また様々、区としてもファミリー世帯の居住、定住促進というところでは、しっかりと考えていかなければいけない課題かなと考えています。","voiceIndex":32,"id":"exchange-011"},{"speaker":"せお副委員長","kind":"質問・要望","question":"すみません、ありがとうあります。物価高騰も関係してきているので、複合的に支援していくことで、いろいろな、多様な子育て世帯の方たちが住めるような環境を整えていただくことが大事だと思います。この前も質問しましたが、転落防止にも配慮されているとか、キッズルームがあるとか、そういったマンションに皆さんが住めるよう、支援をぜひ考えていっていただきたいと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-012"}]},{"id":"topic-02","title":"令和８年１月区営住宅入居者募集","agenda":"令和８年１月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３人とか４人の世帯について、区営住宅で３人世帯、４人世帯というのは、あまりないのではないかとか思ってしまうのですが、そういう世帯の方は、例えばお子さんが障害をお持ちですか、そういった形なのか、そこら辺のイメージを伺いたいのが１つ目です。今回も、直近で３２倍。今まで品川区は住宅ストックが余っているということも説明してきたと思うのですが、改めてその理由を伺いたいと思います。","respondent":"川原住宅課長","answer":"今後の検討としましては、子育て世帯の区外転出がいろいろと今増えているところです。そうした子育て世帯への転入を図るなどの、家賃助成ではない形での子育て支援、住まいの支援を引き続き検討しています。","voiceIndex":39,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"これに１戸当たり平均で言うと２,６００万円、合計２２１億円も投じて、かけて建てるのですかという、この税金の使い方がもう明らかに間違っているのではないかと思うのですが、もう一度、なぜ区営住宅の増設も家賃補助もしないのか。それが、居住サポート住宅とかセーフティネット専用住宅をやっていると言いますが、全然それでは足りないと思うのですが、どのようにお考えでしょうか、伺います。","respondent":"川原住宅課長","answer":"令和３年からスタートして、区内の不動産会社のご協力をいただきながら、１年当たり約１００件単位で入居の促進を図ってまいりました。","voiceIndex":41,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長自身も権利としての社会保障と言っておりますけれども、やはり住まいは人権ということで、やはりすごく、住まいは人権を保障する上での核となるところなのです。そこについて様々やっているのは分かります。そういった補助金を検討して実施していただきたいと、改めて要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"いきなり今の質疑で、子育て世代の転居費用の助成の話が上がり、本会議でも、今もありましたけれども、これは来年度予算に向けて今準備していると、そういうことなのですか。どういうことが今運営されているのか、今、既にありますか。違いますよね。来年度予算に向けて今準備している。要するにどういう支援の中身なのかというのを知りたかったので、現状で結構ですので、分かる範囲で。","respondent":"川原住宅課長","answer":"子育て世帯への転居費用助成は、現行は行っておりません。今、中身については検討の段階ですので、委員の皆様にお示しできるときがまいりましたら、きちんとご説明をさせていただきたいと考えています。","voiceIndex":45,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"こちらいかがかという、現状の考えを伺います。もちろん品川に住んでいる方はいらっしゃいますけれども、家を建て替えて親と２世帯住宅であったり、たまたま物件と自分のお給料の関係で何とかローンが組めたり、もちろん全員が全員というわけではないですけれども、やはり子どもの部屋だったりいろいろ考えると、なかなか品川は難しい。関連の質問ですが、最後にいかがでしょうか。","respondent":"川原住宅課長","answer":"そういった住戸の供給に併せて、様々な子育て世帯の住まいの支援は検討していきたいと考えています。","voiceIndex":47,"id":"exchange-017"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"順番を変えて３から伺っていきたいと思います。区内残留地区における下水道耐震化を行っているということなのですが、まだ残っているところというのはどこにあるのでしょうか。全地区完了の見込みというのはいつ頃になるのか、伺いたいと思います。防災公園等に設置しているマンホールトイレなども使えるようにするためには、耐震化の対象にしていく必要があると思うのですが、いかがでしょうか。","respondent":"関根河川下水道課長","answer":"具体的には、令和２年度までにかけて災害復旧拠点ということで耐震化を進めてきておりますが、その中にマンホールトイレ設置公園というのも位置づけておりまして、その中で耐震化を実施したところです。","voiceIndex":57,"id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"そうですか。確認したいと思います。そこも確認させてください。併せて聞いてしまいますが、上水道の耐震化の記載がないのですが、それはなぜなのかお伺いしたいと思います。この水道についても、私は、品川区として少なくとも区民避難所の耐震化というのは早期に達成する目標を立てるとか、あるいは区としても、状況を把握して区民にお知らせすることが必要ではないかと思うのですが、いかがでしょうか。","respondent":"関根河川下水道課長","answer":"地区内残留地区につきましても、先ほど申し上げたところ以外については実施済みということで、現在の地区内残留地区として指定されているところにつきましては、先ほど申し上げた実施中のところを着実に実施していくという形で考えてあります。","voiceIndex":59,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。区民の皆さんも安心だと思うので、そこはぜひお願いしたいと思いますけれども、東京都に求めていただくというようなことはいかがでしょうかと質問させていただきたいと思います。そのまま次の２番に行ってしまいますが、２番の倒れないまち、かなり拡充しているということでお話があったのですが、今年度からの拡充内容でどれくらいの耐震促進効果があったのか、伺いたいと思います。","respondent":"関根河川下水道課長、大友公園課長、森建築課長","answer":"先ほどの東京都水道局についてですけれども、重要施設への供給ルート等の耐震化ですけれども、先ほど申し上げた避難所ですとか主要な駅等々以外にも。先ほどマンホールトイレ、公園等に設置してあるトイレについて、下水道等の耐震化が完了しているというお話があったのですけれども。総合支援メニューを設定した理由ですけれども、やはり耐震診断を無償化にしてかなり診断自体は増えたのですけれども、工事に進まないというところで。","voiceIndex":61,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは不燃化特区支援事業に移行するなり、そういうのを東京都に求めるべきだと思うのですが、いかがでしょうか、伺います。これを見たら、本当に進める必要があるのですか、この時点で立ち止まって、もう引き返すべきなのではないですかという判断も、私は出てくるのではないかと思うのです。伺いたいのは、区としてそういった数字を算出していただきたいと思いますけれども、いかがでしょうか。","respondent":"関根河川下水道課長、小川木密整備推進課長","answer":"水道の耐震化について、私からお答えします。水道の重要施設への供給ルートの耐震化というところで、避難所と申し上げましたけれども、具体的には小中学校等５２施設ということで、小中学校をメインとして完了していると聞いてあります。ただ、東京都もまた新たな取組として、別の、不燃化特区以外の事業というものを今検討しているところでございまして、その中で新たな助成支援というものも考えられていると聞いてありますので、我々もそういった動きを注視しながら。","voiceIndex":65,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"私、いろいろ言いましたが、特定整備路線について一番の問題は、やはり住民の犠牲だと思うのです。これは品川区が、当時の区長が手を挙げて、東京都にやってほしいと、やるべきだと具申をして、それで進んだというところで、決してもう人ごとではないのです。ぜひそういった考えを持っていただきたいのですが、東京都に求めていただけませんでしょうか。よろしくお願いします。伺います。","respondent":"小川木密整備推進課長","answer":"特定整備路線の整備に関しましては、区といたしましては、やはり延焼遮断帯の形成であったり、避難路、または救援救護路の役割といったところでは、非常に重要な防災まちづくりの取組の一つだという認識です。","voiceIndex":68,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"何だか防災上の課題というとタワーマンションしかないような、こうした主張というのは、やはり私はおかしいと思いますので、まず、意見を述べさせていただきたいと思います。伺いたいのは、当初は地域が限定されて、集中的にやるという議論でしたが、今は区内全域で実施されております。これはどのような政策判断、政策の発展なのか、改めて伺いたいと思います。最初から区内全域でしたか。","respondent":"森建築課長","answer":"除却につきましても、もともとは新防火区域などに限っていたのですけれども、こちらにつきましても、さらに加速させていこうということで区内全域へ拡充してきているところです。戸建て住宅除却工事は除却のみなのかというところですけど、除却のみです。","voiceIndex":71,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"２点目の除却工事ですけれども、そうなのですよ。１面の2)の不燃化特区支援事業は１０地区ということで、これは地区が限定されているのですよね。加速させたいとおっしゃるのであれば、ぜひ区内全域で、除却費だけでなく、引っ越し代や設計監理費や工事費等建て替えに係る費用の一部助成も行うべきではないかと、そういう理屈になってくるのではないかと思うのですけれども、いかがでしょうか。","respondent":"森建築課長","answer":"過去、地域を限定してなぜ集中的に実施したかというところですけれども、やはり予算の面等も含めて、集中的にやっていたのではないかと考えてはいます。","voiceIndex":73,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"予算も含めて、ぜひ区内全域で個々の住宅を安全にしていくというのであれば、今、社会情勢というお話がありましたけれども、いつ起きてもおかしくない大地震に備えるのであれば、直ちに手をつけるべきときだと思うのですが、改めてこの点を伺いたいと思います。１点、私自身、振り返ると、初めは、除却の議論が出たときに、更地にして終わってしまうのではないかという問題意識を持っていたのです。","respondent":"森建築課長","answer":"区内全域に広げることについては別途検討していくことなのだろうと思いますけれども、耐震化というところでは、やはり耐震工事をしていただきたいのがメインになりますので、建て替えについて現在は助成はないですけれども、今後また考えてまいりたいと考えています。","voiceIndex":75,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、やはり一つ一つの住宅を安全にしていくという意味では区内全域に広げていく、こういう考えを持つべきだと思うし、ただ、公園を整備したり、生活道路をセットバックしたり、建物の日影規制を緩和したりなど、こうしたまちのルールづくりなどは地区ごとで行っていくべきだと思うのですけれども、こうした考えはぜひ持っていただきたいと思うのですけれども、最後にいかがでしょうか。","respondent":"小川木密整備推進課長","answer":"そうした観点からは、この西大井五丁目であったり大井三丁目というのは、危険度が３と、さほど高い危険のあるような地区ではないというところで、我々、不燃化促進の取組につきましては、やはり効果的・効率的な防災性の向上を図るため。","voiceIndex":77,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１点だけ。地区名で言うと、西大井と二葉二丁目が対象でした。こうした不燃化・耐震化の一方で、新たな再開発につながっていく、もっといえばタワーマンションやオフィスビルにつながっていく、こうした事業を都市開発課がかぶせてくるというか、重なってくるというのは、区としてはどういうスタンスなのかと思うのですけれども、お考えを伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"区としましても、やはり我々、不燃化促進のほうでは、個々の住宅等も不燃化の促進を図りながら、併せて地域主体のまちづくりも行っていただいて、総合的な災害に強いまちづくりを目指していきたいといったところでは、現在。","voiceIndex":79,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に意見だけ述べます。西大井一丁目、二丁目、三丁目、五丁目、六丁目、二葉二丁目ですか、広範な地域で新たなまちづくりのアンケート調査が今始まって、恐らく上位計画をつくるための材料にされる。高度利用だ、スカイラインだ、魅力あるまちだという理由で高層マンションが建ったり、オフィスビルになったりするのではないでしょうか。そうした中で共同化を進めていく。長くなり、失礼しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-028"},{"speaker":"ゆきた委員","kind":"確認","question":"私からは、３の下水道インフラの機能確保のところで伺いたいと思います。石川県能登半島では、震災のときに、マンホールの液状化が復旧への深刻な被害となりました。建設委員会でも今回視察に行きまして、実際に液状化しているマンホールも確認しました。当時場所によってはマンホールが数十センチから１メートル飛び出している事態も確認したという報道もありました。","respondent":"関根河川下水道課長","answer":"車両通行に支障となるぐらい浮き上がることが見込まれるものについては、冒頭ご説明で申し上げた、弁を設置するという対策を取ってあります。","voiceIndex":84,"id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"私も、事務事業概要で確認させていただきましたが、区内の避難所、災害復旧拠点、あと地区内残留地区、さらには令和５年度より、一時滞在施設や無電柱化している道路などのマンホールとの接続について、耐震化が進められていますが、区民がその耐震化された場所の情報をどう入手していくか、把握できるかというのが課題だと感じますが、ここについてどう捉えているか、お聞きできればと思います。","respondent":"関根河川下水道課長","answer":"耐震化の状況につきましては、私ども品川区で受託をしている以外にも、東京都下水道局が実施しているものもあります。","voiceIndex":86,"id":"exchange-030"},{"speaker":"ゆきた委員","kind":"確認","question":"例えばホームページでも進捗の可視化をして、耐震化完了区間を年度別や完了・未完了で色分けで表示するとか、都の計画を公開したり、区独自で行うとか、品川区も確認させてもらったのですけれども、私が見落としているだけなのかもしれないですが、上下水道管の耐震化状況を可視化するなどしていき、区民への安心を提供していくのも一つだと考えますが、その辺についてお考えをお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"ご提案いただきましたホームページの見える化につきまして、下水道の耐震化を主体として実施しています東京都下水道局、上水道につきましても東京都で全て直営でやってありますので、東京都と連携しながら、どういったことができるかというのは考えてまいりたいと思います。","voiceIndex":88,"id":"exchange-031"},{"speaker":"松永委員","kind":"確認","question":"少し確認なのですが、先ほどの質疑の中で、無電柱化道路とかマンホールのことについては、上下水道、こちらは私道も含まれて、全体という意味でこのような事業になっているのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"この下水道の地震対策として実施しておりますのは、公道下のものなので、いわゆる東京下水道ということで、東京都下水道局の所有している下水道について実施をしているものとなっています。","voiceIndex":92,"id":"exchange-032"},{"speaker":"せお副委員長","kind":"質問","question":"少し細かいところで申し訳ないですが、２番の木造住宅耐震加速化パッケージを、３年間の期限付きの集中的な取組として拡充していったのはすばらしいと思っています。せっかく３年間の期限付きの集中取組なので、対象者を区が把握しているならば、お手紙とか、アウトリーチというか、そういったことはされているのかというのをお聞きしたいです。","respondent":"森建築課長","answer":"過去には、個別訪問等を行っていたのですけれども、現在は行っていない状態です。ただ、皆さんに活用していただきたいので、様々な手法を取りまして、区民の皆さんに対して周知してまいります。","voiceIndex":96,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7273#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":37628,"voices":105}},{"id":"r07-20251126-9","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"文教委員会","time":"午前１０時１０分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"条例の一部を改正する条例、(2)第１４２号議案、学校教育職員の給与等に関する特別措置に関する条例の一部を改正する条例、(3)第１４３号議案","agenda":"条例の一部を改正する条例、(2)第１４２号議案、学校教育職員の給与等に関する特別措置に関する条例の一部を改正する条例、(3)第１４３号議案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"組合とは団体交渉を行ってきた中で妥結をしたのか伺いたいのと、あと義務教育等教員特別手当の見直しで、校務の種類を考慮したものにするというのはどういうことなのか、どう変わるのか伺います。","respondent":"酒川指導課長","answer":"妥結については、したものと捉えております。それから、校務の種類についてですが、これは年々、高まる担任の負担への配慮と理解しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"組合とは妥結したということで、今回、公立の義務教育諸学校等の教育職員の給与等に関する特別措置法の改正に伴う教職調整額、これが引上げになるということで、４％から１０％、これはそれでもまだ足りないと私は思っておりますが、今回、段階的に引き上げていくということですけれども、そうした理由と、区としてはこの１０％引上げで十分と考えているのか、伺います。","respondent":"酒川指導課長","answer":"１０％で十分かという問題についてですが、これについては、処遇改善が図られたということで第一歩と考えておりますが、働き方改革につきましては、この教職調整額の引上げと併せて進めていく、さらに処遇改善が図られていくよう努力していくものと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としても、さらに引き上げていくということで、ぜひ、やはりこの間ずっと残業代が支払われない中で来たところが、一定、第一歩というお話でしたけれども、前進をしたということで、さらに引き上げていく、そしてしっかりと残業代を支払っていくようにしていくことが必要と思います。それが教員不足解消に向けても一歩となると思いますので、区としても取り組んでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"若林委員","kind":"質問・要望","question":"給料表の改正で、毎回そうなのでしょうけれども、（１）と（２）のそれぞれ若年層に考慮したという表現がありますけれども、具体的にこの給与表でいうと、それがどう数字で見えるのか教えていただきたいと思います。","respondent":"酒川指導課長","answer":"なかなか給料表からどこが高まっているかを申し上げることは難しいのですけれども、一般企業の初任給等々が上がっている背景を踏まえ、教員不足を解消していく必要があるということで、若年層に厚みを持たせてあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"若林委員","kind":"質問","question":"ということは、ここでは学校教育職員と幼稚園教育職員でそれぞれ給与月額の較差分、逆に引上げ分が、それぞれ金額が少し違うわけですけれども、この数字よりも、それぞれ今のいわゆる若年層の号給とかが、例えば学校教育職員でいうと３.２４％の引上げ、幼稚園教育職員でいうと３.８％の引上げよりも率とか金額がこの号給では厚くなっている理解でよろしいのでしょうか。","respondent":"酒川指導課長","answer":"その理解でよいと考えています。","voiceIndex":15,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"管理職のことでお尋ねしたくて、教職調整額も管理職の先生方も金額が上がっていっているわけですけれども、副校長先生のなり手がなかなかとか、ということは校長先生もなのですけれども、そうすると、教職調整額が一般の方と同じ比率でいくというところに１つ課題があるのと、あと、先ほどの給料表になるのでしょうか、５級、６級のところ、もちろん一般の方よりも高くなっているのですけど、ただ。","respondent":"酒川指導課長","answer":"そういった中で、僅かながらこの教職調整額を増額することに併せて、このような加算があるわけですけれども、やはりモチベーションと、管理職の先生方の心身の健康を維持していくための方策については、これもまた働き方改革に帰ってしまいますけれども。","voiceIndex":22,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"その辺り、いかがでしょうか。","respondent":"酒川指導課長","answer":"やはり都費の教員ですので、区で対応はなかなか難しいところはありますが、やはり東京都に引き続きの処遇改善については働きかけを行っていくべきものかと考えております。","voiceIndex":24,"id":"exchange-007"},{"speaker":"のだて委員","kind":"意見","question":"都の職員との公平性、平等性に関わるというところで合わせていくべきだと思いますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-008"}]},{"id":"topic-02","title":"文化財の登録","agenda":"文化財の登録","exchanges":[{"speaker":"横山委員","kind":"確認","question":"イベントはどのような内容になるのかと、文化財の登録に当たって、区としての何か変更点ですとか、それから、３月なので、来年度から何か助成等の対象にこちらが入っていくのかですとか、その辺り、どのように変わっていくのかを確認させてください。今後の保存活用の方向性について、何か現段階として分かっていることがあれば教えてください。","respondent":"舩木庶務課長","answer":"年度内に予定している記念講演につきましても、これは一定程度、所管が文化観光戦略の所管にまたがりますけれども、この実施に際しては、様々な媒体を用いて周知を図り、この登録がしっかりとなされたことを区民に関心を持っていただけるように努めていきたいと考えております。","voiceIndex":55,"id":"exchange-009"},{"speaker":"横山委員","kind":"質問","question":"今、ご答弁いただいたのですけれども、基本的には国の制度で、国が様々な制度を用意しているということなのですけれども、区としては、そういった連携協定であったりとか、あと文化観光戦略課と協働しながら、区民の方に関心を持っていただいたりとか、あと周知を行っていくというのが区の役割としてある理解でよろしいでしょうか。","respondent":"舩木庶務課長","answer":"今回につきましては、日頃から広く能楽のことで常設的な能楽の公演であったり、子どもたちを招いたりというところもありますので、こうしたところを、やはりより歴史的文化の価値も、今回登録された背景も含めまして、より興味を持ってもらえるような働きかけは、教育委員会と。","voiceIndex":57,"id":"exchange-010"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、文化はそうですけれども、例えば建築系で、要は建築マニア、建築マニアと言っていいのか分からないけれども、建築が好きな方のそういった観点、学生であるとか、能楽ではなくて建物もすばらしいという部分からのアプローチであるとか、目黒駅から近いので、ホテルと提携して、要は夜間でやるとか、インバウンドに対応した英語つきの舞台をやるとか。","respondent":"舩木庶務課長","answer":"このたびの国の登録という喜ばしいことを踏まえまして、いろいろな働きかけが考えられると思いますが、１つには、最近ですと、能楽体験を品川区のふるさと納税の返礼品に追加していますし、今のご指摘のように、建造物という観点からも興味・関心を持っていただいて。","voiceIndex":59,"id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"国の登録有形文化財ということなのですけれども、重要文化財とかだと、かなり利用したり、そこで見学したりするのに制限があって、すごく注意を払って利用しなければいけなくなるのですけれども、こちらは有形文化財ですから、小中学生が今までどおりに利用することがこの後も大丈夫であるか、貴重な建物の中で体験できることなのであれば、それが１つ。","respondent":"舩木庶務課長","answer":"文化財巡りもそうですけれども、いろいろなメニューへの追加については、どういう連携の取り方、興味関心を持っていただける方法があるかはしっかり考えていきたいと思います。","voiceIndex":62,"id":"exchange-012"}]},{"id":"topic-03","title":"標準服購入費用保護者負担軽減事業","agenda":"標準服購入費用保護者負担軽減事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"電子クーポンを保護者の方に配布するということで、これはどういった形でやられるのか、あと地元の販売店の方がどう関わってくるのか、今までどおり、保護者の方は地元のところで買えるのかということなどを含めて、伺います。","respondent":"石井学務課長","answer":"販売店ですけれども、各学校の指定の制服事業者、全部で６社あるのですけれども、それぞれ、これまで使っていたところで使うことが可能です。","voiceIndex":70,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"ＱＲコードで配布をする。そうすると、販売店で読み取る機械がないといけないと思うのですけれども、そういったものは配備がしっかりできるのかどうか、販売店の負担などはあるのか伺います。","respondent":"石井学務課長","answer":"本クーポン事業を開始するに当たって、これまでクーポンの設計とかも含めて、各６社の販売店のご意見を伺いながら進めてまいりました。１２月３日に、改めてその画面のデモなどを用いた販売店向けの説明会を行うこととしております。","voiceIndex":72,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"地元の販売店が、これまでずっとやられてきたところもあると思いますので、そうしたところが今回の事業で排除されないように進めていただきたい。確認させていただきたいと思います。","respondent":"石井学務課長","answer":"お見込みのとおり、現在の標準服事業者に関しては、本事業の導入に伴って排除されるようなことはございません。","voiceIndex":74,"id":"exchange-015"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"この事業をして、例えば今回使った後に、保護者からの振り返りというのは、ぜひやっていただきたい。ＱＲコードが本当によかったのか、悪かったのかとか、そういった振り返りをしっかりして、この事業の改善を図っていってほしいというのが１点。クーポンで、先ほどＱＲコードをやると、そのままだという話なので、要は天井がない、金額、そこの何か縛りがあるのか教えてください。","respondent":"石井学務課長","answer":"ただ、もちろん物価高騰ですとか、標準服の値段はこれから上がってくるものです。きちんとその辺りについては事業者と連携を密に取りながらやっていきたいと考えております。","voiceIndex":77,"id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そこまでしてくれるのは安心しました。制服は絶対着なければいけないから、申請し忘れることはないと思いますけれども、やはり無償化になってくると、お米なども注文はするけれども取りに行かない、そういう家庭が随分、増えているとお聞きもするので、取りこぼしは絶対ないとは思いますけれども、改めてこういったクーポンの周知をしっかりとしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-017"},{"speaker":"横山委員","kind":"確認","question":"私が聞き間違えているのかもしれないのですけれども、先ほど義務教育学校のお子さんに対しては、現４年生から６年生ですか、７年生と先ほど聞こえたような気がしたのですけれども、現４年生から６年生に電子クーポンを配布ということで、経過措置として考えているという理解でよろしいのか確認させてください。","respondent":"石井学務課長","answer":"そういうケースについては、各学校にいろいろご意見を伺いながら、取扱いを検討していきたいと考えております。配布後の転入に関しては、もちろん入学前に制服を購入できるような形で、きちんと対応してまいりたいと考えております。","voiceIndex":81,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"１１月１４日に、ホームページで既にご案内が詳細にされていますが、それ以降、保護者、ご家庭等からのこれに対してのお問合せはどのような感じですか。","respondent":"石井学務課長","answer":"ホームページ掲載前に、無償化という報道をされていたけれどもどうなんですか、そのようなお問合せは結構いただいていたのですけれども、徐々に、あらかじめホームページ掲載前に、学校を通じて保護者に案内していたということもあったので、ホームページ掲載後については。","voiceIndex":84,"id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"この文面を見て、私も、そうかなと思ったのですけれども、そこら辺についてのご見解を聞きたいのと、あとは、この標準服、６社で、販売店が何店舗、これは金額がこれから決まってくる、もう決まっているのか、について、私が電子クーポンで買う、または本事業で買うこのワンセットは幾らなのかと、それが無償になったというのを家庭が分かるようになっているのかという、その２つ。","respondent":"石井学務課長","answer":"特別支援学校に通うお子さんなのですけれども、今回の標準服無償化事業以外に、例えば修学旅行ですとか、あと補助教材ですとか給食費、そういったことも併せて補助事業を実施しております。","voiceIndex":86,"id":"exchange-020"},{"speaker":"若林委員","kind":"質問","question":"無償化によって、何か恩着せがましく家庭に、お宅様の年間幾ら無償化にしましたと、そういう気持ちはさらさらないのですけれども、やはりお金のことなので、区の立場から言えば財政のことになるので、やはり区の財政を使って、これだけのことを、家庭にということもあまり強調する意図はないのだけれども、区の財政を使って、みんなで出し合った税とかを、みんなで連帯の象徴として分け合っているのです。","respondent":"石井学務課長","answer":"例えば区立学校の補助教材ですとか給食であれば、実際には全部、同じような形で、価格も統一して実施できるものがあるために、そういった現物給付は可能であると考えているのですけれども、例えば現状、補助教材ですとか給食費というのは。","voiceIndex":88,"id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"それからもう１つは、業者に対して悪く言うつもりは全くないのですけれども、無償化になったということで、先ほど金額の話が出ていますけれども、諸物価値上がりの折みたいな、今までの制服の値段より、無償化で、値上げ幅が納得いかないような部分が出てくる可能性がないように、区でしっかりと金額については、もちろん業者がやることですから、どこまで言及できるかあるかもしれませんけれども、今。","respondent":"石井学務課長","answer":"学校を使って一斉に採寸会をやるようなところもあれば、個々の注文受付でやっているところもあります。そういったものについては、各学校を通じて、入学予定の方々に伝達をするです。販売そのものについては、何か学校が関わっているということはございません。","voiceIndex":91,"id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"業者のスケジュールの点については、業者が児童、ご家庭に連絡するということですが、どうしても学校の場所を使って採寸したり、いつだったか、ちょうど行事的なところでうまく合うかなどがあるので、学校の協力も必要になってくるので、そこはうまくきちんと連携を取ってやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-023"},{"speaker":"筒井副委員長","kind":"確認","question":"私からは、確認も含めて、電子クーポンを使ったこうした事業は、自治体で初めてということだったのですけれども、現金を直接渡すと、それ以外の用途に使ってしまうおそれなどあると思いますので、電子クーポンということで、そうしたことは解消されると思うのですけれども、改めて今回、電子クーポン制にした理由をお聞かせください。","respondent":"石井学務課長","answer":"やはりデジタル時代に即応した手法も一定程度、考えていかねばならないだろうという問題意識が初めにありました。例えば現金給付ですと、先ほども少し議論になりましたけれども、各販売会社や学校によって、標準服の値段が違います。","voiceIndex":95,"id":"exchange-024"},{"speaker":"筒井副委員長","kind":"質問","question":"そのコストの話ですけれども、紙だと高いということだと思うのですけれども、今回、電子クーポン導入に当たって、システム業者とかに依頼と思うのですけれども、その業者はどこなのか、かかる費用はどのぐらいになるのでしょうか。","respondent":"石井学務課長","answer":"クーポンの事業者につきましては、ＴＯＰＰＡＮの会社に頼んでおります。これに関しましては、電子クーポンのシステム構築費用のほかに、初めに各ご家庭にご案内を送る通知の発送費用等も全部含めて、１,０００万円弱となっております。","voiceIndex":97,"id":"exchange-025"},{"speaker":"筒井副委員長","kind":"質問","question":"その１,０００万円弱は、今回そのシステムが出来上がったら、大規模更新はなく、そのままずっと使えるということでしょうか。","respondent":"石井学務課長","answer":"その維持費用は各年度かかってくると考えております。","voiceIndex":99,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"今、大変流行しているということで、何か対策は行っているのかどうかと、今後の見通し、子どもたちが元気に成長していただけたらと思うのですけれども、区の対応はどうなっているか伺います。","respondent":"石井学務課長、染谷保育施設運営課長","answer":"動きとかを追っていますと、２年前の状況は、ここから少しずつ落ち着いてきて、また２月頃にはやり出すという過去の例がございましたので、引き続き各学校においては。見通しにつきましては、先ほどの学校と、登園自粛の時期については、令和６年度、昨年度と比較して、やはりかなり早くなっていて、同様に令和５年度の傾向と近い部分があるというようなところを。","voiceIndex":111,"id":"exchange-027"}]},{"id":"topic-04","title":"令和６年度品川区立学校における不登校・いじめの状況","agenda":"令和６年度品川区立学校における不登校・いじめの状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"すみません、聞き逃したところがあって、資料の左下のところで、相談・指導を受けていない児童・生徒が、義務教育学校では０人だったということで、その前段、何で０人だったのかを聞き逃してしまったので、もう一度伺いたいのと、あと全体としては８％の人が指導などを受けていないということで、今後、こうした子どもたちへの対応をどうされていくのか。実際、そうした子どもたちがどういう状況なのか。","respondent":"丸谷教育総合支援センター長","answer":"従前からあるマイスクール、こういったものも含めまして取り組んでいきたいと考えております。今年度は、中学校義務教育学校１５校に巡回指導教員が配置されておりますので、継続的な指導が受けられない生徒は限りなくゼロに近づいていくだろうという見込みです。","voiceIndex":119,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"マイスクールの受け止めは分かりました。不登校巡回指導員の方が今、１５校に配置されているということで、今後さらに増やしていくことは考えているのか伺いたいのと、今、校内別室指導もやっていると思うのですが、その効果と現状を伺います。併せて、不登校数が１年生と７年生で大きく減少したと、資料にも書かれているのですけれども、理由をどのように分析されているのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"不登校の児童・生徒、１年生と７年生が減少したですけれども、やはり不登校になり切る前に、校内別室指導で救えるケースですとか、また、コロナ禍に急増したというような状況もありまして、それが現在、落ち着いたというところで、学校に通うといった意識。","voiceIndex":121,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の考えを伺います。それと、いじめですけれども、１つ確認なのですが、いじめは解消したというところで、児童では６３.４％、生徒では７５.６％となっておりますが、このいじめが解消したという条件はどういうものなのかを、まず確認させていただきたいのと、あと重大事態が昨年度は５件だったということで、その受け止めを伺います。その傾向も含めて伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"令和６年度は５件の重大事態が起こってしまいましたが、法に基づいて適切に対応している表れではありますけれども、こうしたものが一件でも減らせるように、学校、家庭、地域が一丸となって取り組んでいくべきものと捉えております。","voiceIndex":123,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"併せて、やはりこの不登校、いじめなどをなくしていくためにも、教育環境をよくしていくことが必要だと思いますけれども、教員の多忙化を解消していくですとか、少人数学級を実現していく、また、子どもの権利条約など、しっかり子どもたちが理解し、他者を尊重できるようにしていくことが１つ大きく減らしていくことになると思うのですけれども、いかがでしょうか。","respondent":"丸谷教育総合支援センター長、酒川指導課長","answer":"各学校では、学校風土の改善に向けて、昨年度から研修等も行い、取り組んでいますけれども、引き続き、学校風土の改善を目指すことで、不登校やいじめについて、減らしていけると考えているところです。子どもと向き合う時間を増やすことが、一層の認知につながると捉えておりますので、教員の多忙化解消には今後も努めてまいりたいと考えています。","voiceIndex":125,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後の多忙化解消、そして子どもの権利条約など、教育環境をよくしていくことを一緒に取り組んでいただいて、不登校・いじめ、なくなるのが一番ですけれども、できるだけ減らしていくということで取り組んでいただきたいと思います。それで、２年生では認知件数が改善できたということですけれども、何か新たな取組をやったとか、どのようにして改善されたのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そうした取組を、ほかの学校にも周知していくことで、区全体を挙げて、小さないじめでもしっかり認知をして対応していくと、そういう全体での取組につなげていきたいと考えておりまして、現在それに取り組んでいるところです。","voiceIndex":128,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"１,０００人当たりの不登校児童・生徒の推移の表で、令和６年の生徒数が、国との比較で少し多くなっているというお話があったのですけれども、この辺りの分析は、どうしてなのか、区としてどのように考えているのかというのを教えてください。","respondent":"丸谷教育総合支援センター長","answer":"継続的な指導を受けられていない６１人の児童・生徒についてですけれども、この中でメタバースに登録している児童・生徒がいるかどうか、クロスとしての分析はできておりません。しかしながら、登録はしているという児童・生徒も混じっているとは捉えております。","voiceIndex":131,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"いじめの重大事態が一件でも減らせるように、ぜひお願いしたいと思っているのですけれども、そうしたいじめの認知をして、それから重大事態というのは、徐々に起きていって、この５件は発生しているのか、タイムラグといいますか、一つ一つの重大事態のいじめの内容によっても変わってくると思うのですけれども、いきなり重大事態に発展してしまうのか、その辺りの平均的な部分であったりとか。","respondent":"丸谷教育総合支援センター長","answer":"ケース・バイ・ケースの対応になっています。","voiceIndex":133,"id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"質問","question":"もちろん個別の事情はたくさんあるのですけれども、それでもマイスクールに来られる児童・生徒はいいという考え方もあるのですけれども、マイスクールの在り方、そういった意味で、マイスクールでは非常に一生懸命、指導していただいて、マイスクールに来ていただければすごく手厚くやられているのは存じ上げているのですけれども、そういったマイスクールにもなかなか来られないという現実。","respondent":"丸谷教育総合支援センター長","answer":"昨年度は校内別室ができたことで、これがかなり大きく影響、効果が出ていると捉えていまして、４教室で８８人に収まったということで、通常、年末から年明けにかけて、新規の受入れがなかなか難しい状況が令和５年度まで続いていたのですけれども、昨年度は。","voiceIndex":136,"id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこで卒業していって次の進路に行くというのは、マイスクールで随分、高校にそのまま行く子たちもたくさんいるとお聞きしているので、ぜひ、幾つかある行き場所の中でも、より学校的なところで一生懸命やられているので、そこの充実を求めていくのですが、そこだけ最後にお願いします。","respondent":"丸谷教育総合支援センター長","answer":"そういった特性もありますので、まず学校から案内できるのはマイスクールということで行っていますので、今後も、そういった学校とも連携を密にした教室であるように努めてまいります。","voiceIndex":138,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、連携ということで、情報のやり取り、今日はこうでこうだったとか、来たとか、そういうのは非常に学校と密にやっていただいているとお聞きしているし、学校としても、安心してマイスクールに行ってもらっているというところがあるので、今お話があったように、しっかりとそういった方向で頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-037"},{"speaker":"まつざわ委員","kind":"質問","question":"１点だけ。いじめの状況で、悪口が非常に多くて、ＳＮＳ、パソコン、これの件数というのが少ないです。これはそれこそ今、教育委員会も学校も一生懸命、指導してくれている、そういうＳＮＳ指導のたまものであるのか、この数字はどう考えるのかというのが１点。それと、また逆に反比例して、生活リズムの不調がよくある。","respondent":"丸谷教育総合支援センター長","answer":"スクールカウンセラーやスクールソーシャルワーカーの関わり、現在、ＨＥＡＲＴＳに要望、相談があれば家庭支援も行っている段階です。早期に関わることが、やはり大切だという認識を我々も持っておりますので、支援体制についても今後の検討課題と捉えております。","voiceIndex":142,"id":"exchange-038"},{"speaker":"筒井副委員長","kind":"質問","question":"いじめについては、認知件数を増やして、重大化を防ぐ目標があって、非常に立てやすいと思うのですけれども、不登校の問題の最終的な目標は、学校にもう一回来ていただく、復帰していただくことなのか、その目標の立て方がなかなか難しいと思っているのですけれども、まず不登校の解消、その辺りはどのようにお考えなのか、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"児童では１３２名、割合にすると３３.２％、中学生、生徒では９４名、割合では２２.７％の生徒が学校に復帰、登校できるようになったですので、今後は、不登校の数だけではなくて、復帰できた人数ですとか割合ですとか、こういったものもしっかりと調べて。","voiceIndex":145,"id":"exchange-039"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"原因については、生活リズムの不調だとか、あと不安・抑鬱など、ご病気の場合もあると思うので、原因はすごく様々あると思っているのですけれども、結構難しい対応だと感じておりますが、この生活リズムの不調だとか不安・抑鬱だとかの、こうした原因が上位を占めていることについてどうお考えなのか、また、その解消についてどうお考えなのか教えてください。","respondent":"丸谷教育総合支援センター長","answer":"そんな中で、学校が安心できる場づくりを目指していかなければならないというのが、我々の認識です。そういった意味で、学校風土を上げていくことに現在、取り組んでおりまして、子どもたち同士、教員と子どもの関係性・絆づくりも深めていきたいと考えています。","voiceIndex":147,"id":"exchange-040"}]},{"id":"topic-05","title":"品川区教育振興基本計画・品川区教育ビジョン アクションプラン","agenda":"品川区教育振興基本計画・品川区教育ビジョン アクションプラン","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"誰もがウェルビーイングな状態になることはいいことだと思うのですけれども、ウェルビーイング教育になるとどうなるのか、押しつけ的なものになってしまうという危惧もありまして、実際どんなことをやるのかを伺いたいと思います。","respondent":"唐澤教育施策推進担当課長","answer":"これまでの教育からの変更点ですが、冊子は２ページ、３ページ、電子ですと５ページ、６ページの内容になりますが、これが教育振興基本計画でも示している学びの羅針盤です。","voiceIndex":155,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでの教育改革プラン２１は、基盤、土台だということでご説明いただきました。ウェルビーイング教育は、各教科の中でやっていくということなのですけれども、具体的にはどういった形になるのか、少しイメージできないので、何か具体例があれば伺いたいのと、あと、先行で実施している学校もあると書いてあったと思うのですが、そうしたところがどんなことをしているのかをお聞きしたいと思います。","respondent":"唐澤教育施策推進担当課長、丸谷教育総合支援センター長","answer":"ウェルビーイング教育につきましては、具体例は後ほどまたお答えしますが、今、お話のあったとおり、考え方として、まずは子どもたちに知ってもらう形で進めておるところです。市民科の中でウェルビーイングについて学ぶことがあれば、各教科の中で、例えば国語やそういったものの題材の中から、何か主人公の行動やそういったものを通してウェルビーイングについて考えてみるといったような取組も今後。","voiceIndex":157,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"分かったような、分からないようなですが、でも分かりました。これは小学校前期課程、５・６年生で可能な限り実施すると書かれておりますけれども、実際、今、何校でやられていて、どのような形でやられているのか、教科担任制ですから担任の先生が担当ではない教科のときには教室からいなくなってしまって、ほかの教科の人が授業をやりに来るということです。それをどうやられているか伺います。","respondent":"酒川指導課長","answer":"そのほかにも学校の特色を活かしてとか、教員の能力を活かすとか、学級経営の能力に課題がある学級がある場合等も踏まえて、学年の中で、例えば国語を専門にやる教員、社会科を専門にやる教員、体育を専門にやる教員というように教科を分担して実施している学校もある状況です。","voiceIndex":160,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"教科担任制が５・６年生から、通常、中学校からだと思うのですけれども、品川区では早めに実施されているところが、今、２校あって、これから５校になっていくというところで、教育関係に携わっている方から指摘を受けまして、やはりまだ小学生の年齢で、担任の先生が教室からいなくなってしまう、同じ人がずっとそばにいないという中で、子どもたちが不安になるというご指摘をいただきまして。","respondent":"酒川指導課長","answer":"子どもの不安ですが、１人の担任とより濃密な関係で過ごしたい子どももいる一方で、１人の教員との関係に苦しみを感じる子どももいる中で、実施している学校からは、よりたくさんの教員が、一人一人の子どもを見ることができるようになったとか。","voiceIndex":162,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"その次に冊子でいうと２６ページの学力定着度調査、学力テストですけれども、今回、区が実施している学力テストでは、スケジュールのところで、令和９年度実施について検討と書いてあるのですけれども、これはどういったことを検討するのか伺います。","respondent":"酒川指導課長","answer":"学力定着度調査ですけれども、現在、様々な調査を学校に実施、依頼している中で、一度、教育委員会が実施している調査を俯瞰してみて、精査する必要もあるだろうという中で、この学力定着度調査についても実施の是非も含めて検討するものです。","voiceIndex":166,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"学力テストについては、区が実施しているものは精査する必要があると考えたということですけれども、そういう考えに至った経緯を伺えればと思います。習熟度別指導は、私はかねてから言っておりますけれども、できる子、できない子で分けられてしまって、できない子がよりストレスを感じる、自己肯定感が弱まってしまう問題があると思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"冊子の５１ページで、不登校支援ということで、ここに新たに学びの多様化学校の設置と記載があるのですけれども、これはどういうものなのか伺います。５２ページの特別支援教育の充実では、特別支援教育推進計画をつくっていくということで、今後、検討していくと思うのですけれども、どういった内容をお伝えしようと今のところ考えていらっしゃるのか伺います。","respondent":"丸谷教育総合支援センター長、唐澤教育施策推進担当課長","answer":"不登校状態にある子どもを受け入れるための新たな学校で、他自治体、全国的にも現在、設置が進んでおりまして、本区においてもそういったものも、他自治体等も注視しつつ、設置に向けた検討を進めていこうという考えです。特別支援教育の推進計画につきましては、現在も様々なお子様、ニーズ等ありますので、環境整備、必要な支援は現在も実施しておるところですが、長期的な視点の中でそれをどう考えていくのか、検討していく形となります。","voiceIndex":171,"id":"exchange-047"},{"speaker":"まつざわ委員","kind":"質問","question":"冊子の６８ページです。夜間等の電話対応委託を令和２年から教職員の働き方改革の一環としてやっているという話ですけれども、これは全区立小・中、義務教育学校で対応してるとありますが、これは本当にやっているのか。言い方はごめんなさい。例えばうちも６時過ぎに先生が電話をくれて、対応が随分、夜間でも実際やっていらっしゃるわけです。そこら辺の現状を教えてください。","respondent":"酒川指導課長","answer":"状況によるとは思いますが、全校で実施しているものですけれども、子どもの安全に関わる内容ですとか、緊急を要する場合にはそれによらない場合もあるとは考えております。","voiceIndex":176,"id":"exchange-048"},{"speaker":"まつざわ委員","kind":"質問","question":"冊子のページだと１１になります。個別最適な中で、要は品川区は授業の改善を図る中で、学びの差が開いている。その上で、この教育ダッシュボードを構築要件として、学びの充実を図るというのですけれども、例えばこの教育ダッシュボードがそもそも何なのか、教育ダッシュボードをやると、具体的に教師のマネジメントはどう軽減されるのか教えてください。","respondent":"唐澤教育施策推進担当課長","answer":"実際には、今後、検討していく形にはなるのですけれども、例えば児童・生徒の氏名や性別、出欠状況、またはこれまでの支援とかアセスメントなどが一覧で分かることによって、校内委員会や今後の支援に係るそうした委員会の資料準備ですとか。","voiceIndex":180,"id":"exchange-049"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えばこれももう少し会派としても言い続けて、先ほどの答弁だと、おっしゃるとおり、時間をかけてというのは分かるのですが、大分、時間もかけてやってきているのですから、令和９年と言わずに、ある程度、これをいわばやると、策定をすると決めたわけですから、時期を例えば短縮するといった検討をして、支援員の充実や整備をさらに進めていこうという意気込みも必要だと思うのですけれども。","respondent":"唐澤教育施策推進担当課長","answer":"今回、ここで載せているものは、現時点の計画という形で載せていますが、策定に当たっては教職員の方から意見を聞くなどは、現在、実施している市民科と同様に必要と考えています。","voiceIndex":182,"id":"exchange-050"},{"speaker":"横山委員","kind":"質問","question":"私からは冊子の１２ページのアクションプランの進行管理をお伺いしたいのですけれども、こちらの見直しなのですが、毎年度の見直しに応じて、加筆・修正していきますということですが、具体的にどういった形で見直されていくのかと、子どもたちの意見はこういった見直しにどのように反映されていくのかを、アンケートというところは書いてあるのですけれども、詳細を教えてください。","respondent":"唐澤教育施策推進担当課長","answer":"子どもの意見集約につきましては、この大元の教育ビジョンにつきまして、５年間の計画という形で子どもから意見集約しておりますので、また、新たに令和１１年が終わったところで、そうした検討に入っていくものと考えております。","voiceIndex":185,"id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"冊子の４７ページの保護者アンケートおよび児童・生徒アンケートの実施で、令和８年にＣＢＴ化予定とあるのですが、こちらの例えば理科とか、教科の分析でＣＢＴ化は少し前の文教委員会でも出てきたと思うのですけれども、そういったご意見に対するアンケートのＣＢＴ化によるメリットとデメリットについて、どのようなものがあるのか教えてください。","respondent":"酒川指導課長","answer":"デジタル化したときに大きなデメリットになるのは回収率等があるかと。ただし、デジタル化することによって、より精緻な結果の分析ができるといったこともあると思いますので、専門部署等とも連携しまして、より効果的なデジタル化を図っていきたいと思います。","voiceIndex":187,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問・要望","question":"５１ページの不登校支援で、先ほどもあったのですけれども、学びの多様化学校の開設ということで、こちらが令和８年に開設検討、令和９年に実施計画の策定で、令和１０年に分教室型の設置になっているのですが、まだこれから様々、計画が具体的なところに入っていくと思うのですが、こちら、分教室型を検討された理由と、あとどういった形で、まずどこか特定の学校にそういった分教室型をつくっていくのか。","respondent":"丸谷教育総合支援センター長","answer":"分教室型は、割とハードルが低く、東京都内でも複数の自治体がこの分教室型を進めているということもございまして、まずは分教室型を目指そうという考えに至ったものです。施設等につきましては、現存の区施設を様々検討いたしまして、決めていきたいという考えです。","voiceIndex":189,"id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つか。１つ目はＰＴＡの支援とあったのですが、ＰＴＡの在り方も様々いろいろな議論があるのですけれども、現状でＰＴＡという組織がもし分かれば、もうやめましょうとなった学校がどれぐらいあるかお分かりですか。次がタブレットの話で、更新の時期だと思うのですけれども、更新して、どういう課題があったから、どういう点を改善するために更新していくのか。これは質問ではないです。","respondent":"舩木庶務課長、石井学務課長、酒川指導課長、米田教育次長","answer":"もう１校、ＰＴＡという名前ではなく、名称を別の名称に変えて活動されているところがありまして、いずれにしましても。私からは、１人１台端末の更新についてお答えいたします。令和２年度の３月から１人１台端末の普及を図ってきました。地域連携を進める上では、学校地域コーディネーター、部活動アシスタントコーディネーターを配置しまして、教員の負担軽減につなげているところです。こちらにありますように、既に着手に至っているものについては、これまで改革も具体的に示していますので。","voiceIndex":192,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"確認","question":"タブレットについては、もう普及したので、今度、活用をどうやっていくか、学校も含め、教育委員会も含め、進めていくと確認しました。区独自にもこういった形でやっている。私も今すぐにこれはと申し上げられないので申し訳ないのですけれども。改築については、令和８年度の予算の中で教育の思いがどれだけ出てくるかを期待していますので、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-055"},{"speaker":"筒井副委員長","kind":"質問","question":"私からウェルビーイング教育についてお聞きしたいと思います。先ほども、のだて委員からご質問がありました、重点施策。１番目なので、非常に重要なことかと思うのですけれども、結局、先ほどのご説明でも、具体的にどのようにやっているのか、少しなかなかつかみづらかったのですが、各教科に合わせて、ウェルビーイングについて教えてください。どのようにやっていくのか。","respondent":"丸谷教育総合支援センター長","answer":"具体的には、ウェルビーイングを考えていったときに１つの指標を考えています。","voiceIndex":199,"id":"exchange-056"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問","question":"私から何点か質問をします。家庭復帰後の継続支援体制の強化が課題として挙げられていたと思うのですけれども、こちらは様々、児童相談所の部分であったり、子ども家庭支援センターの部分であったりあると思うのですが、それぞれその子ども家庭支援センターと児童相談所と具体的にどういったところを強化していったらいいと考えていらっしゃるのか、区のお考えをそれぞれ教えてください。","respondent":"長谷川児童相談課長、吉野子ども家庭支援センター長","answer":"これは主に施設等に措置されている子どもがなるべく早い段階でご家庭に戻れるよう、今、ある課題を多職種の間で捉え、情報共有しながら、家庭にもアドバイスをしながら進めていくというものになりますけれども、その過程におきまして。子ども家庭支援センターとしての役割ですけれども、実際にご自宅に伺わせていただいて、家庭の状況等を調べします。","voiceIndex":207,"id":"exchange-057"},{"speaker":"横山委員","kind":"質問・要望","question":"議会でもいろいろ議論になったりしますけれども、乳児の社会的養護まで至らないように、予防的に様々、品川区では政策がとられていると思うのですけれども、保健センターであったりですとか、あとはおむつの宅配ですとか、お米ですとか、いろいろ子ども家庭支援センターであったりとかほかの児童相談所以外のところで予防的な取組が行われているので、そうしたところの児童相談所の。","respondent":"長谷川児童相談課長、吉野子ども家庭支援センター長、丸谷教育総合支援センター長","answer":"今、様々な課題意識を共有させていただきましたけれども、こちらとしましても、特に不登校の部分ですとか、児童相談所のみ。ここで、妊娠期から支援につなぐというところで、早期発見、早期対応をこちらで図っている状態です。これからも連携を強めてまいりたいと思います。","voiceIndex":210,"id":"exchange-058"},{"speaker":"まつざわ委員","kind":"質問","question":"そもそも論ですけれども、虐待案件が児童相談所に一元化でありますけれども、この表を見て、子ども家庭支援センターの協議ケースと児童相談所の協議ケースがあって、合同会議があって、対応機関の決定と書いてあります。これは結局この会議をどう決めて、どういう方針がこの合同会議の中で行われるのかを少し詳しく教えてください。","respondent":"長谷川児童相談課長","answer":"この会議の場では、こちらでこういう通報が入ったのだけれどもそちらで知っている情報があったら欲しいということもあれば、アセスメントシートに基づき判断したところ、そこまでリスクが高くないので、子ども家庭支援センターの対応でお願いしたいという場合もありますし。","voiceIndex":215,"id":"exchange-059"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、多分、現状、一時保護の場合は男子が１５１％、女子が１６４％ということで、特に中高生の女子の受入れが課題ですとお聞きすると、例えば本来は児童相談所で受けなければいけない部分もこういうふうに受け切れないと、例えば子ども家庭支援センターに少しお願いするとかいったケースがないのか。要は、受け入れようとしても、もうぱんぱんな場合はどうにもならないではないですか。","respondent":"長谷川児童相談課長","answer":"基本的に児童相談所で対応すべき案件に関しては、全て児童相談所のほうで対応しております。場合によりましては、例えば人手の問題とか即応性が必要な場合に、子ども家庭支援センターと合同会議を開いた上で、共に動くことはケースによってはあるかと思います。","voiceIndex":217,"id":"exchange-060"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"だから、東京都と連携があるのであれば、専門職というのはもう、例えば都にもお願いしたり、ケースワーカーを増やしたりして負担を減らす体制は、ぜひつくっていただきたいと思います。子ども食堂も十幾つある中で、だから情報共有をして支援の抜け漏れ防止を図るとあるけれども、結局、そこのルール、マニュアルはあるのかというのが少し疑問なのですが、それを教えてください。","respondent":"長谷川児童相談課長、柴田子ども施策連携担当課長","answer":"児童相談所としては、関係機関の気づきがあって初めて認知できる部分がありますので、まず、気になる児童がいたら、その都度、こちらにお知らせいただきたいことと、一度関わった以上、支援が終わったからといって。こちら利用に当たっては、措置（解除）が予定されている子どもに、早めにこの事業を周知して、施設にいる間、里親にいる間から認識をしていただく。","voiceIndex":219,"id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問","question":"３番の課題ですけれども、もちろんの児童相談所の中で、先ほど可能な限り、所内とかいろいろなことをおっしゃって、しっかりやられているのですが、やはり財政面や、あるいは施設、整備の面からすると、区のほうの企画なり財政に働きかけて、そちらの方面での体制の整備が必要になってくると思うのですけれども、そういった面についての当局との働きかけ。","respondent":"長谷川児童相談課長","answer":"財政や施設整備に関してのリクエスト状況で、以前にもお話しいただいたかと思うのですけれども、その後、特にこちらからまた新たに財政課に話しかけることは特段してございませんので、区全体の調整の中で話は進んでいくものと認識しております。","voiceIndex":223,"id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"施設の課題のところは、様々な施設という話は今、お答えのとおりだと思うのですけれども、例えば中高生女子の受入先確保とか、課題のある子どもへの適切な受入れ体制の確保とか、やはり児童相談所だけではなかなかいかないところがあって、やはり当局にも財政的な形が必要だと思うので、そういうところも含めて、ぜひ働きかけていっていただきたい。","respondent":"長谷川児童相談課長","answer":"我々所管としては、目の前にある支援に一生懸命注力をしまして、事故が起こらないよう、職員の連携を強めているところである一方で、以前、企画サイドにも情報は提供しておりますので、全庁的な検討の場で議論されるものだと認識しています。","voiceIndex":225,"id":"exchange-063"},{"speaker":"のだて委員","kind":"質問","question":"発達に課題のある子どもが増えているということで、実際、今、そうした子どもは何人ぐらいにいらっしゃるのか。そこをまず伺います。","respondent":"長谷川児童相談課長、原品川区児童相談所長","answer":"定員拡大あるいは施設増設に関しましては、先ほど高橋委員にご説明したとおり、全庁的な議論の場で検討されていくものだと捉えておりまして、私どもとしては、まず目の前にある子どもたちの支援に全力で注力しているという段階です。発達課題のある児童について、少し補足的に説明します。いわゆる発達障害といえるようなカテゴリーにある、例えば持って生まれた、生まれながらにしてとかというような子どもも決してゼロではありません。","voiceIndex":228,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"発達に課題のある子どもの受入れも全庁的に議論していく必要があるということなのですか。今、区の考えがあれば伺いたいと思います。それと、今、里親ですとか児童養護施設、乳児院に入っている方が８２人ということで、ここでも区内には乳児院はないと思うのですけれども、そうした施設の増設も区内で整備していくことも必要なのかなと思うのですが、いかがでしょうか。","respondent":"長谷川児童相談課長","answer":"もう１つ、施設の誘致というお話かと思いますけれども、これも先ほどの答弁と重なりますが、特別区と東京都で、いわゆる協定を結んでいる関係上、区にたとえ設置したとしても、区がその施設を独占利用できるわけではなく、割愛の対象になってしまうというところでは。","voiceIndex":231,"id":"exchange-065"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"えのした議員の質問のところです。ほかの自治体や東京都の例もありますので、その点から。もう１つは、東京都の都費の時間講師あるいはほかの区でも港区や杉並区では経験年数が積み重なれば時給もアップしていくという報酬の表を、港区、杉並区はほぼ東京都に近いのですが、経験年数と需給の関係について、現状は２,６８０円で一律なので、その点についてどのように改定していく考えがあるか、お尋ねします。","respondent":"酒川指導課長","answer":"現状ですけれども、現在、実費支給に向けまして、関係課と協議、調整を図っているところです。経験年数の加味については、今のところ、検討の俎上に載ってございません。","voiceIndex":236,"id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"質問","question":"例えば１０年、１５年やられた方が区費の時間講師をやろうとしたら、今の一律の金額からすると、やはり経験や資質からすると、ほかの自治体なんかと比べてしまうと報酬が低くなってしまうということで、非常に資質の高い講師の方を採用するためには、そういったことも必要と思いますが、経験年数と時給との関係についても、もう一度、伺います。","respondent":"酒川指導課長","answer":"経験年数ですけれども、今のところ、経験年数を加味すると、経験年数の浅い任用中の講師の報酬額が下がるといった課題もあるところから、これは絶対に実施しないということではございませんで、今後、まずは交通費の実費支給をした結果、どのようになった等々の成果を踏まえて。","voiceIndex":238,"id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"交通費は今、お話のあったように、東京都、他自治体等を見て、少なくとも同等かあるいはそれ以上の状況にしていただきたいというのが１つです。２つ目の経験年数は今、おっしゃったとおり、やはり１年目、２年目の方にとっては時給が高いわけです。検討するというお話だったので、それは今すぐはまず交通費で、経験のほうは、まだ来年度はそこまでいかない認識でよろしいでしょうか。","respondent":"酒川指導課長","answer":"おっしゃるとおりです。やはり財政的な課題もあると思っていますので、どのような人を配置していくのが最適かという、総合的に判断する中で検討していくことになろうかと考えています。","voiceIndex":240,"id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もう１つは、本当に管理職の先生方が、時間講師を探すのにで大変苦労しているので、それはもうご存じだと思うので、そこがやはり先ほど前の話題にありましたけれども、授業に穴が空いたりといったことになってしまうことにつながりますので、ここはぜひ教育委員会の後半に先ほど思いという話がありましたけれども、思いをしっかりと財政的なところ等、進めていっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"会計年度任用職員の時給の問題で、私たちも全体としてということですけれども、長年勤めても給料が上がらない問題を指摘してきました。やはり、先ほども高橋委員からありましたけれども、経験年数を積んでいけば、より充実したものが提供できるということになっていくと思いますので、ぜひ、そこは私からも時給アップをしていくことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7225#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":67682,"voices":252}},{"id":"r07-20251126-5","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"総務委員会","time":"午前１０時１０分～午前１２時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、特別職の１３４、１３５、１３６、１３７号議案のほうですけれども、これは審議会の答申を受けて、区長が判断するのかなと思うのですが、そういう下で、区民から見ると、企業の賃金も上がったとはいえ一部ですし、中小業者や自営業等の皆さん、フリーランスの皆さんは依然上がらずという下で、さらに物価高騰が押し寄せている、長引いているという下では、直接区民から選ばれている私たち議員や。","respondent":"藤村総務課長","answer":"今回、特別職報酬等審議会におきましては、今回の勧告だけでなく、社会情勢ですとか、他自治体の動向ですとか、そういったところを総合的に踏まえて判断ということになっておりますので、引下げを踏まえてというところではないかもしれないですけれども。","voiceIndex":6,"id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"本来、公務員給与改定と同時に、区民の生活をどう支えるかという生活パッケージが私は提示されるべきだと思います。今回の給与改定ですが、私は物価上昇分の平均８万円から１０万円の給料アップならば、理解はできますが、職員の平均給与が３０万円、区長をはじめ、議長、我々議員などは４０万円以上も上がるということに対しては、賛成はできません。ご見解をお聞かせください。","respondent":"宮尾人事課長","answer":"今回、委員、また議員から、議会からこのようなご意見をいただいたということはしっかりと受け止めて、今後の仕事にまた取り組んでまいりたいと考えています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"そういう実態というのを品川区として、人事委員会勧告が来ても、そういう状況を見て、現実を見て、果たしてこれでいいのだろうかというところ、一歩踏みとどまるということも必要だと思うのですが、今、平均値で出ているからというお話でしたが、実際、平均には見えないのですが、その辺りについてもう一回だけご答弁ください。","respondent":"宮尾人事課長","answer":"そういったことも含めますと、今回も含め、人事委員会で出された結果というのは、しっかりと尊重していくことが望ましいと考えています。委員からいただいたご意見もしっかりと踏まえて、我々は今後の仕事に取り組んでまいりたいと考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回のこの議案に対しては、物価が上がった年間８万円から１０万円に対する給与アップに対しては、私は賛成できますけれども、ほかのパーセントで３０万円も４０万円も年収が上がるということ自体には、賛成いたしかねます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"質問で言いましたけれども、区民の理解を得られるということが大事だと思います。今の社会情勢や経済状況を見るならば、上げるべきではないと思います。委員長がいろいろお話しいただきましたけれども、今の状況を見て、理解を得られる状況かといえば、そうではないと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"松本委員","kind":"提案","question":"維新も反対です。これはこれまで一貫した態度で、区議会議員の報酬については反対させていただいています。なので、これは議会側からも、本来は議員の報酬は幾らが適切なのか、この社会情勢を考えて、これだけ区民が苦しんでいる中で、どの程度なら適切なのかというところを、こうしたことを前提に諮問しなければ、こういう結果になると。逆にそれは議会側から提案すべきかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"賛成です。委員長おっしゃっていましたように、私も長年やっておりますので、その経緯は分かっております。物価の状況によっては変動していくというのは妥当なのかなと思っています。ただ、改善をしなければいけないことは多々ありますので、それは議会の中での議論の項目であって、この場で話を進めることではないと思いますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"松本委員","kind":"意見","question":"２年前まで我が会派は、この特別職、議員を含めて全部反対しておりましたが、昨年、賛成いたしました。それは、私の所属する日本維新の会が政治と金の問題について極めてぐらぐらしていて、本来、身を切る改革と言っておきながら、どうなのだという対応をしていた。そこから１年たって、今何が起きているかといったら、残念ながら赤旗に報道されてしまったように、秘書の関連会社という話が出てきている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"賛成です。特別職の話は先ほどさせていただいて、一般職のほうですけれども、こちらの算定の基準などで、従前、２年前までは反対していました。先ほどと同様、我が党の極めて恥ずかしいようなことがありましたので、こちらも賛成とさせていただいたのは今年ですが、その状況が、考え方によってはさらに悪化しているという状況ですので、こちらも我が会派に反対する資格はなしと考えますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-009"}]},{"id":"topic-02","title":"第１２１号議案、令和７年度品川区一般会計補正予算","agenda":"第１２１号議案、令和７年度品川区一般会計補正予算","exchanges":[{"speaker":"西本委員","kind":"質問","question":"鈴ケ森小学校が不調に終わったということで、なぜということで、現状を教えてください。喜ばしいことではあるのですけれども、何が起きているのですかということ。この経費と、それから収益という兼ね合いで、予算の中では歳入のほうが多くなっているのかなと思うのですけれども、経費に関わるという現状なのか、経費がかかったとしても増やしていくという方向なのか教えてください。","respondent":"加島財政課長、宮澤税務課長","answer":"それが今回、７２億円の予定価格に対しまして、５億円超のオーバーとなったということで、所管のほうで改めて今回、最新の単価等で試算等を行いまして、再入札に備えたいという考えです。なので、寄附があれば、そのパーセンテージが経費としてかかるという形になっておりまして、寄附額の大体、返礼品の調達費用も含めて、５割以下が経費にかかっているです。","voiceIndex":82,"id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"不調については、要は、こちら側の都合で再契約という理解でいいのですか。７２億円でやっていたものが、計算してみたら５億円上がっているということで、それをもう一度やり直しという形の理解でよろしいでしょうかということで、確認させてください。９月は別にしても、ほかのところで１桁どころではないではないですか。こういうのがすごくヒットしたとか、そういうのがあれば教えてください。","respondent":"加島財政課長、宮澤税務課長","answer":"今後につきましては、予算編成段階で、発注時期の単価の動向というのを適切に反映させていくとともに、従来どおり３社から見積りを取りまして、それを発注時期を見越して取得していくということをやっていきたいと考えているところです。もう一つは、ヒット商品といいますか、人気の品、実際に寄附を押し上げているものというのも、特定の人気の品がありますけれども、そういった返礼品を用意することによって、寄附額が上がってきたです。","voiceIndex":85,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"不調のケースで、それはよくないです。難しいのは分かります。かなり深刻だなと思います。それから、ふるさと納税は何があったのですか。何か人気のキャラクターとかを使ってやったのですか。それだったら何となく、これだけあるのはそういう力が働いたことなのだなとかと分かるのですけれども、どういうものでヒットしたのかなと思うのですが、いかがでしょうか。","respondent":"宮澤税務課長","answer":"一方で、体験型というくくりにはなりますけれども、例えば楽天トラベルまたはＪＡＬのダイナミックパッケージといった、品川区を宿泊先とする旅行も返礼品として用意しているところです。","voiceIndex":88,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"返礼品についてお聞きしたいのですが、これは約１億６,９００万円入って、それは寄附が大半なのかもしれないのですけれども、もし寄附がなければ、経費として、事業費として８,０００万円以上かかってしまうということですか。というと、もし寄附がなくなれば赤字に転落するという状況になっているのですか。教えてください。","respondent":"宮澤税務課長","answer":"経費の部分なのですけれども、寄附があれば初めて経費が発生するということになりますので、寄附がなければ支出は、基本的な部分はないということになります。","voiceIndex":90,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"東京の中では、少なくとも相当の企業数、建築会社があるので、そういうことも私は努力していただきたいと思うし、決まった企業群で品川区がやっていたら、簡単に３社か４社だったら、カルテルを結ばれたら値段は上がるだけで、言いなりになってしまうではないですか。このような手法というのは誤解も招くし、私はやはり改善するべきだと思うのですが、その辺りについてご見解をお聞かせください。","respondent":"佐藤経理課長","answer":"区の事業者の選定のお話ですので、私からご回答いたします。区では、区内事業者の育成ですとか、区内経済の活性化という観点から、従来から区内事業者で受注可能なものについては、区内事業者を条件として発注を行っております。","voiceIndex":92,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"だから、そういう状況がきちんと担保されていないから、このような不調になる事例も私は生まれるのだと思うのですが、そういう心配は経理課でされないのですか。そういうことも改善していかないと、皆さんの税金で成り立っているわけですから、そういうところの改善ということも考えられないのでしょうか。もう一度だけご回答、ご見解をお聞かせください。","respondent":"佐藤経理課長","answer":"区内事業者に条件をしているというところをもって、事業者間で何か不正な行いがあるのではないかというお話ですけれども、これに関しては、電子入札を導入しまして、ほかにどういった事業者が参加しているのかは分からない状況にしているというところと。","voiceIndex":94,"id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"最後ですけれども、財政課で今度は少し入札予定価格を上げて、入札をまた皆さんに募集するということですが、昨日のインフレスライドでも値段が上がったのは平均３％です。それを思うと、今回またさらに上乗せして価格を設定するというのは、何か不思議なような気がするので、意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-016"},{"speaker":"松本委員","kind":"意見","question":"私からは、ふるさと納税についてなのですけれども、５割ルールが厳格化されたというのが少し前にありまして、今回の補正予算だけですけれども、補正予算の歳出と歳入で計算すると、この費用が大体４９.６％ぐらいで、結構ぎりぎりなのかなと思えます。これは本当にマックスで、例えば懸念するのは、５割を超えてしまうと制度から排除されるというのがあるのではないか。","respondent":"宮澤税務課長","answer":"委員ご指摘のとおり、経費を５割以内に収めなければいけないというところで、経費を算出していますので、委員ご指摘あった、例えば配送料が上がる場合という形になりますと、経費が上がる場合は寄附額を見直して、寄附額を上げるという形を取るということを想定しております。","voiceIndex":97,"id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"２３区は１,０００億円を超えてしまったという状態かと思います。野田元総務大臣もこれは見直ししたほうがいいと。委託のところで、先ほどの話にも５割ルールで、どうしても３割が返礼品でも、残りの２０％のうちのかなりの部分が業者に流れてしまっているという、これも問題がある制度だと思っています。どうにかできるのかと考えたら、これは東京が全部取ってしまうと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-018"}]},{"id":"topic-03","title":"令和８年度労働報酬下限額に係る品川区公契約審議会の答申","agenda":"令和８年度労働報酬下限額に係る品川区公契約審議会の答申","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これを幾ら決めても、実際その会社で本当に渡っているのですか、適正に労働者に賃金が払われているのですかというところまで踏み込まないと、これは絵に描いた餅で、何にもならないのではないですか。その辺りについてはどのようにお考えでしょうか。","respondent":"佐藤経理課長","answer":"実際そこで働いている労働者の方から、もらっていないということがあれば、区に申請というか、申告いただける形になっておりまして、それを受けて区としましては、確認あるいは調査という形を取って、必要な勧告を出すというところまで条例で決めておりますので。","voiceIndex":115,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"区としても、それを調べなければ区民の方も納得しないし、本当に労働者を守れないという観点から協力してほしいという、そこまで踏み込んで私は見るべきではないかと思うのです。皆さん賃金を払えば、きちんと賃金をどのように払ったという明細書が出るわけですから、そこまで踏み込まないと、そのようにやっています、報告書をもらいます、報告書など幾らでも書けるではないですか。","respondent":"佐藤経理課長","answer":"今回、公契約条例を制定、議決いただきましたけれども、その前年度に有識者に入っていただいて、公契約条例の在り方について検討会ということで開かせていただいて、条例をどのような形にするかということを検討いただきました。","voiceIndex":117,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"何か対応してあげないと、せっかくいい条例をつくったのですから、私は今後踏み込んでやっていただきたいと思います。それで、仕事が増えると言いますけれども、賃金の明細表、我々給料をもらっている方は皆さん明細表が出るのだし、あとは何時間働いたというのも、簡単に数字として出せるわけですから、そんなに負担はかからないと思うので、ぜひいい方向に持っていくように努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-021"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認させてください。１の（１）のところに９０％を乗じて得た額と書いてあるのですが、９０％というのはどこかの目安みたいなのがあるのでしょうか。別に８０％でも８％でもいいということになるので、根拠はどこにあるのでしょうかということと、労働報酬下限額ということは、下請のところの末端の額のことを言っているのですか。どの部分においての下限額なのか教えてください。","respondent":"佐藤経理課長","answer":"２点ご質問いただいたかと思います。一つは、工事の分野での９０％の根拠というところです。今回、審議に当たりましては、既に条例を運用している他区の事例等も委員にお示ししたところです。","voiceIndex":120,"id":"exchange-022"},{"speaker":"西本委員","kind":"確認","question":"そこの中の下限、労務単価というのはそのまま出すのではないのですか。それが１０％の差があるということは、何を想定されているのですかということが１点と、それから、下請という本当に末端で働いている方々の下限で適用されるということなのですけれども、さっきの須貝委員の質問にもあるように、それを誰が確認するのですかという話です。誰がやるのですかということを教えてください。","respondent":"佐藤経理課長","answer":"そうしますと、熟練の度合いによって段階があるということを前提に考えますと、下限額を平均で取ってしまいますと、それ以上の段階を設けなければいけないということで、事業者に過度な負担になるのではないかというところで、一定のそれより下というところで。","voiceIndex":122,"id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"下請の方々までこれが周知されているのかというのは、報告を受けることになるということなので、それを監視というか、調査というか、確認するということの流れができてきていたのかなという思いがあります。なので、必ず報告をしていただいて、末端の働いている方々の給料にどのように反映されているのかということは、しっかり見ていただきますようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も今、須貝委員、西本委員が言ったように、労働者に給与がきちんと渡ることが大事だと思うのですけれども、今後、１２月以降に区長が令和８年度の労働報酬下限額を告示ということで、世田谷区はホームページで職種ごとに下限額を出しているのですが、そういうことに区もしていくということでいいのかというのと、あと、もし下限額より低いようであれば。","respondent":"佐藤経理課長","answer":"２つご質問いただいたかと思います。１つ目は告示の仕方というところですけれども、これは委員ご指摘のとおり、他区も同様ですが、委託、指定管理の分野および工事、工事のほうは職種ごとという形で告示することを予定しております。","voiceIndex":125,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"よろしくお願いします。それで、申告しづらい状況があるかもしれないというところでは、そこは区からぜひ、本当に低い場合は申告してくださいということで、積極的に呼びかける、そして申告しやすい状況を、区としてぜひつくっていただきたいと思うのですけれども、いかがでしょうかということと、あと、資料の３ページ目の、３番の委員からの意見。","respondent":"佐藤経理課長","answer":"２点ありまして、労働者の方が区に相談なり、申告しやすい状況というのは、こちらとしても考えているところですので、先ほどと同じになってしまいますけれども、他区の事例などを見ながら、これから検討していきたいと考えております。","voiceIndex":127,"id":"exchange-026"},{"speaker":"塚本副委員長","kind":"意見","question":"今回の公契約の審議会には、労働組合の団体からも２名ほど、たしか入っていると思います。","respondent":"佐藤経理課長","answer":"労働者の方から申告いただく際もサポートいただけると考えておりますので、来年度以降、運用に向けて頑張っていきたいと考えております。","voiceIndex":129,"id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"私からも１点、ご質問します。来年度以降も審議会で、この基準を丁寧に見ていただきたいと思うのですけれども、審議会の開催については、日程ありきとかではなくて、議論をして、まだ議論を尽くす必要があるときには、柔軟に回数を増やすなどして、議論を尽くしてしっかりと納得できる協議を経て、区長に対し答申できる内容を固めていただきたいと思いますので、その辺り、考えを確認させてください。","respondent":"佐藤経理課長","answer":"来年度以降もそういった形で考えておりますけれども、審議会の委員の議論の中で、ほかの日程、あるいは追加してということがあれば、対応していきたいと考えております。","voiceIndex":131,"id":"exchange-028"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"それに対して、質問の中にありました高橋しんじ議員のところでは、警察と、それから区の見解の乖離があるという話です。今年の５月２日に、ホームページでもこれについては公表されているのですが、証拠不十分という形で答弁をなされているのですが、何をもって証拠不十分なのか、何をもって警察の見解と違うということを言っているのか、まずそこを確認させてください。","respondent":"川村コンプライアンス推進担当課長","answer":"調査結果を受けました区の対応としましては、まず所管部長より当該職員に対し、厳重注意の措置を行い、当該備品の返却を命じまして、後日返却した旨の報告を受けました。","voiceIndex":135,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"刑法第２５３条業務上横領罪に該当するものではないということなのですが、ただ、まず物品は何ですか。そこは言えませんか。何だったのでしょう。もちろん、相手側とこちらの誰か、個人情報がありますので誰かまでは言えないと思うのですけれども、どういうものかというのは公表できないのですか。","respondent":"川村コンプライアンス推進担当課長","answer":"物品は何だったかというご質問についてなのですけれども、通報者を特定できないというのが、一般的に聞いた場合だけではなくて、内部の職員等が聞いた場合にも、通報者の特定につながらないよう配慮する必要があると考えておりますので、申し訳ございませんが。","voiceIndex":139,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"それで、分からないのが、外で使ったのですか。どこで使ったのですか。何のためにどういう形で使われていて、これは備品なわけです。どこがどこに、誰が管理しているものか。現在、どういう状況になっているのですか。返したというのは、どこに返したのですか。区に返したという意味でいいのですか。関連団体に返したということですか。そこがよく分からないのです。","respondent":"川村コンプライアンス推進担当課長","answer":"お答えできる範囲となりますけれども、備品につきましては、こちらが確認したときに、業務上使用し、保管してあったというところで、使用場所というところは把握できるものと思われます。返却につきましては、借りたところに返したという意味での報告です。","voiceIndex":141,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"借りていたものを返しているという証拠はあるのですか。要は関連団体だか、どこかよく分かりません。関連団体と書いていないから、どこか分かりませんが、関連団体の備品なわけです。それを使っていた。返したのは、関連団体からの備品という一覧の中に、それは入っているということでいいですか。そこに返したということの証明がきちんと伝票等で、備品管理の中でもなされているという感覚でいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-032"},{"speaker":"石田（秀）委員長","kind":"質問","question":"公益通報のことについて、高橋しんじ議員の質問を私も聞きました。松本ときひろ議員の質問も聞きました。事実です。ここに書いてある。だけれども、公益通報者には、警察はそういう考え方もあるのではないですかと言った。だから、それを議会が調査して、何か引き出しの中にあったものが備品で、それが何で、どれをどうして何に使ったかというのをここの議会でやるのは、話がずれてきていると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-033"},{"speaker":"西本委員","kind":"確認","question":"今やっているのは確認です。私が聞いているのは、確認をしているだけです。それは職場で机に保管されているのを確認したという形になっているのは、見ているわけではないですか。だけれども、それをきちんと返したという確認は、どうされているのですかというのを聞いているだけです。それを確認していないのだったら、きちんと返したということを確認していないということではないですか。","respondent":"川村コンプライアンス推進担当課長","answer":"西本委員のご質問にお答えいたします。区といたしましては、備品の返却を命じ、後日返却した旨の報告を受けた。これが確認の事実です。","voiceIndex":147,"id":"exchange-034"},{"speaker":"西本委員","kind":"確認","question":"誰が返したのか、誰が確認したのですかということです。誰が報告をしてきたのですか。これは証拠不十分と言うけれども、返したと言っているのだと、返した、受け取ったという、そういうのはあるのですか。それはこの関連団体から、きちんと確認を取れているのですか。確かに返してもらいましたということになりましたか。それを確認させてください。","respondent":"川村コンプライアンス推進担当課長","answer":"前提として申し上げましたけれども、通報者の特定につながらないようという制約の中でお答えしておりますが、こちらがきちんと返却されたというところは、報告を受けて確認しておりますので、これ以上のご回答は差し控えします。","voiceIndex":149,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"どこという名前を言ってほしいとは言っていません。私は関連団体という言葉しか使っていないのです。関連団体からそれを受け取りましたという報告はいただいたということでよろしいですか。","respondent":"川村コンプライアンス推進担当課長","answer":"こちらとしましては、返却されたことはきちんと確認しております。","voiceIndex":151,"id":"exchange-036"},{"speaker":"西本委員","kind":"確認","question":"確認したのですね。分かりました。それで、６月、そして、この報告があったのは今年の５月です。だけれども、警察との見解の乖離はないと言っているということが、意味がよく分からないのです。警察が言っていることと乖離がないということは、警察は横領的な行動ですと言っているのだから、そのような認識になるのではないですか。そうしたら、それに応じた処分が必要なのではないですか。","respondent":"川村コンプライアンス推進担当課長","answer":"区の調査結果が出たタイミングと、警察の見解が質問で示されたタイミング、前後関係はお分かりかと思いますけれども、それを踏まえましても、警察では立件を予定していないということから、警察でも本事案は。","voiceIndex":153,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"今の立件されていないということで、だから乖離はないと。だから、警察の見解と区の見解に差があると言っているのです。だけれども、それを区は、証拠不十分だから、返却されて、厳重注意で終わりという形になっているので、この見解が異なっていやしませんかという話なのです。それはどうなのですか。見解は違っていますよね。品川区と警察との見解は違いますよね。それはどうなのですか。","respondent":"柏原区長室長","answer":"立件されていないというところは、どういう理由で立件をしないというところになっているかというのは、課長も言いましたけれども、詳細なところまでは分かりませんが、ただ、調べたところと同じ立ち位置に立っているのだろうというところは想定もできますし、事実。","voiceIndex":155,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"すみません。今、委員長が言った処分なのですけれども、５月に公表になりました。公益通報は去年です。今年、半年ぐらい、かなりの時間をかけて調査したのでしょう。５月に出てきました。それの答えを聞いて、警察に通報者も相談しているわけです。その上で、だから終わっていないのです。この間の質問の答えは、警察の見解を踏まえて再度見直しをするということは、しないということだったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"だから、時間差があって、警察の見解が出てきた後の調査はしていないのです。そこはどうなのですか。今の質問は、行政の答えとしては。今、委員長が言っていただいた流れで言うと、警察の見解も含めて乖離はないというのは、今回の一般質問で分かった話であって、それに対しての再度見直しを図るとか、それに対しての対応を考えるとかというのは、何も言っていないではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-040"},{"speaker":"西本委員","kind":"意見","question":"だから、それをやるべきだというのを高橋しんじ議員が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、それをきちんと考えていただきたい。なぜかというと、それがうやむやになっているということになると、また別の問題が発生してしまうので、それがしっかり返されているのか、備品が帳簿上どうなっているのかというのは、きちんとお調べになったほうが私はいいと思っていますので、ぜひすぐやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7275#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":40985,"voices":173}},{"id":"r07-20251126-10","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7199#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":3083,"voices":16}},{"id":"r07-20251127-21","meetingId":"r07-cm11","date":"2025年11月27日","dateIso":"2025-11-27","committee":"子ども若者支援・共生社会推進特別委員会","time":"午前１０時００分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"初めのところから伺いたいのですけれども、このフリースペースのところなのですが、本当にフリースペースをすごく熱心にやっていただいて、きめ細やかにいろいろなところと連携しながら、多くの若者が救われているのではないかなという思いがしているのですけれど、ここで、これからの重点取組というところで、令和１１年度の目標値というのが書かれているのです。","respondent":"柴田子ども施策連携担当課長","answer":"それを踏まえまして、区といたしましては、必要な需要はあるというふうに見込んでおり、適地が見つかり次第、新たな拠点、第２のフリースペースといいましょうか、そういったところを整備していきたい、なるべく早くと考えているところです。こちらが１点目です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点で言えば、ヤングケアラーについてやはりきちんと知識として持つというのが、その子ども一人一人に対してしっかりと目に留めていくということにもつながっていくのではないかなと思うのですけれど、そこのところでは、このアンケートをやったのは令和４年なので３年前になると思うのですが、それから、このアンケート結果を受けてどんな取組がされているのか、そして、もう本当。","respondent":"柴田子ども施策連携担当課長、吉野子ども家庭支援センター長","answer":"こちら現在、鋭意探しております。決してたまたま見つかったからやるというわけではなく、本当に積極的に探しています。まだ、先方もあることだったりいたしますので、明言は避けします。アンケート以降の研修などを実際やっておりまして、令和６年度も区立小学校義務教育教員向けの研修、それから、様々な方たちに、例えば配食委託先の介護事業者であったりとか、区社会福祉協議会であったりとか。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"ヤングケアラーを支援するために必要だと思うのはどのようなことですか、という設問もあって、そこのところで、教職員がヤングケアラーについて知ることということと、子ども自身がヤングケアラーについて知ること、保護者がヤングケアラーについて知ること、それから子どもが教職員に相談しやすい環境をつくることというのが、すごく多い数字として出ているのですけれど、そういう点では。","respondent":"吉野子ども家庭支援センター長","answer":"学校の公開授業のほうなのですけれども、なかなかやはり、働きかけてはいるのですが、校長会というのがありまして、そこで、ぜひお願いしますということで働きかけてはいるのですけれども、なかなか手を挙げていただけるところが少ない状況でありますので。","voiceIndex":12,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に学校に求められることが多くて、大変だなと。それなのに、その先生たちのゆとりがあまりにもなさ過ぎるので、学校の教職員のゆとりある体制というのが、本当にこの点からも必要だなと。","respondent":"吉野子ども家庭支援センター長","answer":"確かに、養護教諭の方ですと、例えば兄弟がいて、その子の面倒を見ていたりなどといったこともあり得ると思いますので、今後なのですけれども、やはりそちらの学校のほうにはさらに働きかけていきたいと思っています。","voiceIndex":14,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この間、ピルコンの包括的性教育の問題でも養護教諭を対象にした研修が行われたというふうに聞いたのですけれど、そういうところでは、養護教諭のところに救いを求めてくるというか、そういう部分というのはすごくあると思いますので、先生たちは、養護教員も忙しいとは思うのですけれど、養護教諭は特にそういう研修はいろいろぜひともやっていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"なので、先ほど、タブレットにヤングケアラーとか、いじめに関しての情報を入れていくというお話があったのですけれども、本当に困ったときなどにはっと思い出してもらえるように、プッシュして情報を、ふだん自分が、これでいいのだと思っている、実は独りぼっちの子などにもうまくつながるように、こちらから手を伸ばしていくような形。","respondent":"東野福祉計画課長、柴田子ども施策連携担当課長","answer":"全国的に見ると、孤独・孤立の相談というのが、実は１０代の子からの相談が一番多いというような結果も出ておりますので、品川区は実はそこまではいっていないというところはあるのですけれども、そういった対策につきましても。ですので、児童センターの職員もフリースペースのことを認識しておりますので、子どもたちが、児童センターがいいのかフリースペースがいいのか選べるような形を取れるように、体制のほうは整えているところです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ご近所さんとの関係性をつくるということで、少し注目してはいるのですが、結局、そういったイベントをやって、恐らくその場では知り合い、お店の人が来て少し出かけるきっかけになったりなどはいいかなと思うのですけれども、その場だけでなく、つながりを継続しないといけないなとは思っておりまして、出会いの場とか居場所等とか相談とかも。","respondent":"東野福祉計画課長","answer":"つまり、地域でのサードプレイスをどうつくってどう運営していくかみたいな話も、現在取り組んでいるところです。来年度の事業として、福祉計画課のほうで、コーディネートしながら取組を進めたいと考えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"澤田委員","kind":"質問・要望","question":"私からは、まず、資料の１つ目のところで、アンケート調査というところの吹き出しの中で「多くの子どもや若者が理不尽な状況に置かれていることが多いと感じる」というところを、子ども・子育て・若者支援団体の意見として挙がっていると思うのですけれども、この理不尽な状況というのが、具体的にはどんなことが挙がっていたのかなというのを、もし分かれば教えていただきたいなと思います。","respondent":"柴田子ども施策連携担当課長","answer":"資料の左下のアンケートの吹き出しの部分です。こちら、こども計画を策定するに当たりまして、子どもの意見でしたり、子どもを支援する団体にヒアリングを実施し、生の意見をいただいたところです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"澤田委員","kind":"意見","question":"今後の方向性なのですけれども、強めていって包括的に支援できる体制を構築していくというふうに書かれているのですが、課題解決していく中では、その苦しみの根本というか悩みの根本というところをひもとくことが大切だと思うのですけれども、その要因の中には障害というものが潜んでいたりすることもあると思うので、そちらとも連携していただけたらなと思っているのですが。","respondent":"柴田子ども施策連携担当課長","answer":"様々団体が、子ども向けの事業ですとか説明会、講演会を実施する際は補助金というものも用意しておりますので、そういったところで、団体の活動を支援して、より元気に活動してもらう応援をしています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"澤田委員","kind":"質問","question":"最後になのですけれども、ヤングケアラーのところで、先生の理解促進のための研修だとか、子どもたち本人へのアプローチというところは先ほど、ほかの委員からもお伺いしていたと思うのですが、私からはやはり保護者の方が、もしかしたらうちの子ヤングケアラーかもしれない、ヤングケアラーにしてしまっているかもしれないというところをまず、知っていただくことというのも大切かなと思うのですが。","respondent":"吉野子ども家庭支援センター長","answer":"今、企業のほうにも少し話をしておりまして、いわゆる企業での、ヤングケアラーとは何かというところから、そういったところのものを始めているところですので、少しずつ広げていきたいと考えています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"澤田委員","kind":"質問・要望","question":"今も様々取組を進めていかれているということが分かったのですけれども、ぜひ進めていただきたいなということと、あと、以前、学校での研修で、いじめ予防みたいなことだったのですけれど、随分昔でＣＡＰというものに私も子どもの学校で、親の勉強会みたいなものがあるからぜひどうですかというので行ってみたら、参加者４人しかいなくて、結構、仕事されている方も多いですし。","respondent":"吉野子ども家庭支援センター長","answer":"今、様々なツールを使って、いろいろな方に呼びかけて、そういったところの理解をしていこうと考えていますので、少し参考にさせていただきたいと思いますので、なるべく広げていきたいと考えております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"西村委員","kind":"確認","question":"幾つか伺わせてください。子ども若者応援フリースペース、エールしながわのところでさっきもちらっと触れていただいたと思うのですが、この目標値が令和５年度から令和１１年と大分幅がありますけれども、倍近くになっているところを、子ども若者応援フリースペースとエールしながわ、それぞれ伺えればと思います。そちらをお願いします。","respondent":"柴田子ども施策連携担当課長","answer":"目標値に関してそれぞれお答えします。フリースペースのほうなのですが、令和５年度実績６９９に対して目標値１,５８３。倍以上となっているのですけれど、こちらは、フリースペースに来る子どもは一定数おりまして、いるだけも、もちろん結構なのです。","voiceIndex":31,"id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"改めて伺いたいのですけれども、子ども若者応援フリースペースは結構お越しになっている方々の年齢層の幅が広いイメージがありまして、上のご年齢の方も結構、大人の年齢の方もいらしたなという印象があるので、最近の傾向を教えていただきたいのと、エールしながわもご年齢が大人世代が多いのかなという印象がありまして、改めてお聞かせください。","respondent":"柴田子ども施策連携担当課長","answer":"エールしながわの年齢に関しましては、こちら細かい統計というのは取っていないのですけれども、利用の対象が１５歳から４９歳というふうにエールしながわのほうはなっておりまして、毎月のヒアリングで、ケースの中身などを聞いているところ。","voiceIndex":33,"id":"exchange-013"},{"speaker":"西村委員","kind":"質問・要望","question":"特に適地を、子ども若者応援フリースペースみたいなものをどんどん増やしてほしいという思いは私もありますが、先ほども少し児童センターのお話出ましたけれども、児童センターにいてもいいし、不登校のお子さんなどは図書館にいてもいいのだよという雰囲気は醸成をしていただいていると思っていまして、ただ現実なかなか、不登校のお子さんでいうと、行っているかというと。","respondent":"上野子ども育成課長","answer":"委員ご指摘のありました、不登校のお子さんに対して、いつでも来ていいよというところでの周知ですけれども、児童センターも開かれた場所として現在もやっておりますが、今後、もっと幅広いお子様に来ていただけますように、積極的に周知に努めてまいりたいと思います。","voiceIndex":35,"id":"exchange-014"},{"speaker":"西村委員","kind":"質問・要望","question":"１点、どなたにご答弁いただけばいいか分からないのですけれど、ある自治体で子ども宅食という取組を強化している自治体が、都内ではないのですが、ありまして、私もずっと要望していることでして、不登校になった時点で子どもが孤立してしまう。","respondent":"吉野子ども家庭支援センター長","answer":"ヤングケアラーのほうでは、配食支援というものをやっております。こちらのほうですけれども、少しずつですが利用者のほうは増えております。このときに、やはり、その家庭の状況であったりとかといったところも含めて確認のほうさせていただいている状況です。","voiceIndex":37,"id":"exchange-015"},{"speaker":"西村委員","kind":"質問・要望","question":"ヤングケアラー支援についても、令和５年度と目標値が倍ぐらい、ヤングケアラー支援だったら３倍ぐらいありますので、ここも伺いたいのと、あと、左側のアンケート調査で、ＨＥＡＲＴＳの専用電話が、困ったときに相談できると思っていない、認識がないというのが８９.５％ということだと思うのですが、アンケート結果ですから正しいのだと思うのですけれど、子どもたちに聞いていると。","respondent":"吉野子ども家庭支援センター長、柴田子ども施策連携担当課長","answer":"私からなのですけれども、ヤングケアラーの、こちらの目標値のほうなのですが、令和６年度、１４２件の相談件数がありまして、令和７年度、１０月末ですけれども、前年度を超えておりまして１４４件になっております。委員からお話しいただきましたＨＥＡＲＴＳに関してなのですけれども、所管が違うもので、どういった周知等をしているかというのは存じ上げないところがあるのですが、こども計画を実施するに当たって取ったアンケートのほうも。","voiceIndex":39,"id":"exchange-016"},{"speaker":"西村委員","kind":"意見","question":"すみません、１点だけ最後に、ヤングケアラーが認知されていくごとにご相談件数が増えているということはよいことだと思うのですけれども、お伝えいただける範囲で、今の品川区のお子さんで、ヤングケアラーだというご相談がある方の事例というか、どのようなことで子どもたちが困っていて相談に来ているのかというのがもし、個人情報になりますが、お伝えいただける範囲でお願いします。","respondent":"吉野子ども家庭支援センター長","answer":"最近特に多いのは、親御さんが病気で、いわゆる精神疾患の方が多いというところで、要するに、家の、親御さんの代わりに家事をやったりとか買物をやったりとか、そういった事例が増えてきております。","voiceIndex":42,"id":"exchange-017"},{"speaker":"西村委員","kind":"質問","question":"そうなったときに、ＬＩＮＥ相談も大分頑張っていただいているので、子どもたちの相談するルートというのは何が一番多いですか。","respondent":"吉野子ども家庭支援センター長","answer":"先ほど、学校のタブレットというのをお伝えしたのですけれども、それ以上に、やはりＬＩＮＥ相談というものがとても多いです。こちらのほうで友達登録もされておりまして、こちらが少しずつですけれども増えておりまして、ここが一番多い形になっています。","voiceIndex":44,"id":"exchange-018"},{"speaker":"西村委員","kind":"意見","question":"ＬＩＮＥが使えるということは、まもるっちがあるので、小学生はなかなかスマホ持っていませんので中学生以上がやはり多いのかなと思いますので、次なる課題は小学生の部分が、早めに発見してあげられるといいなと思います。感想ですが、ありがとうあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"私は、孤独・孤立対策についてお聞きしていきたいと思うのですけれども、まず、３ページのこれまでの取組のところから、品川区の地域福祉に関するアンケート調査を令和４年に行ったとのことですが、こちらの回答の対象となる方というのはどのような方なのか、また、回答率だとか、あと回答していない方はどのような背景があるとお考えか、お聞かせいただければと思います。","respondent":"東野福祉計画課長","answer":"手元に回答数、回答状況の資料はないのですけれども、資料の設問にあったものを取り上げたということでご理解いただければと思います。","voiceIndex":47,"id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。資料がなかったということで、結果お聞きして、例えばですけれど、回答していなかった方の背景というのもどのような状況なのかなというのをお聞きしたかったというところです。こちらのほう、具体的に教えていただけますでしょうか。","respondent":"東野福祉計画課長","answer":"先ほども説明させていただきましたが、区民１人３回まで無料ですというようなご案内をしています。","voiceIndex":49,"id":"exchange-021"},{"speaker":"せらく委員","kind":"提案","question":"４回目以降の料金の面だとか、次の新しい紹介先への引継ぎだとかそういったところ課題かと思うのですけれども、やはり３回はしっかり相談を受けてカウンセリングを受けて、そこから新しい相談先、カウンセリング先というのが、利用者にとって結構負担があるのではないかなと思いますので、その引継ぎの方法だとか、４回目以降のところの検討、今年度から始めたものなのでこれからだとは思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問","question":"フリースペースの資料にいただいている丸ポツの２つ目の２行目に、本来ならば社会全体で担うべき問題、それがサードプレイスの相談拠点に集中している、云々とあるのですが、ここで言うところの、本来ならば社会全体でという、その「社会全体」という意味は、どういう存在、団体、中間団体、担い手を言っているのか、教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"こちらでお示しさせていただきました、本来、社会全体というところが何を指しているかですが、身近なところで言えば、もちろん家庭、それから所属先である学校だったり職場、また、暮らす地域、それから、専門的な機関である医療機関ですとか。","voiceIndex":52,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"そこに行政がやはり積極的に前に出てくると。その中で、家族の機能を、行政という機関を通じて、マンパワーなので、担い手をそこに当てていくという取組なのですけれども、そこのところはどういうふうな形で、現時点の発生している課題に対する対応と、そうさせない、川上の段階でしっかりと対応していくというところの、ここのバランスというのはどういう状況で展開するのか改めて教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"そういった形で、出口というものをしっかりとつくっていくことによって、問題が解消され、入ってきてもそこであふれることはなく、人生のつながりで、通過点としてフリースペースが利用してもらえれば、そのように考えて、出口のところに力を入れているです。","voiceIndex":54,"id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"具体的な部分で、出口という表現でありました。この両方の時間軸というか見方が必要なのだろうなと思うのですけれども、その辺をどういうふうにして、ソフトについては、ある程度年度ごとのアジャストなどができると思うのですが、ハード整備はそういう部分が非常について回ることかなと思うのですが、どういう視点で取り組んでいるのか教えていただきたい。先ほどから様々なアプローチの仕方ありました。","respondent":"柴田子ども施策連携担当課長","answer":"ただし、委員のおっしゃるように、４年後、５年後、必要ないものになってはいけませんので、それはやはり地域性とか、地域のそれ以外の環境にもよると思いますので、新たな拠点を設置するに際しましては、子どもたちの意見をしっかり聞きながら反映させていくというところ。","voiceIndex":56,"id":"exchange-025"},{"speaker":"つる委員","kind":"質問・要望","question":"これは全体のいろいろな取組として、ぜひ考えていただきたいなと思います。私もＸのいろいろな品川区の情報発進を見ると、定時で送るようになっているから、例えばお昼と夕方などにどーんといろいろなものが１０件近く入っている。だからやはり、そういう意味でも工夫というのですか、もう少しいろいろなものが進んでいると思うので、そういうのも取り入れながら。仕掛けですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-026"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今お話聞いていて、個人的に少し要望だけ伝えします。先ほどからやはり、すごく課題たくさんあるなというのは感じております。本当に課題解決するべきヤングケアラーなどといった問題たくさんあると思います。要望です。何か一言お願いいたします。","respondent":"吉野子ども家庭支援センター長","answer":"私ども、子ども家庭支援センターのほうは、やはりそういった家族というところは大切にしていまして、あくまでも支援という形でやっております。ある程度支援が行き届きましたら、そこは当然、その家族の機能というところを大切にしていきたいと考えておる次第です。","voiceIndex":59,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どういう形でつくられていくのかということを伺いたいのと、相談支援の推進ということでもここで書かれているのですけれど、この相談支援の推進というのはどういうことでしていくのか、また、その下の、当事者等への支援を行う人材の確保・養成・資質向上などというのは、どこがどういうふうにしていくのかという辺りを少し教えていただきたいというのが１つです。","respondent":"東野福祉計画課長","answer":"その４回目以降の支援を受けたい方についてなのですけれども、マイシェルパのほうから区へつないでいただくというようなこともありますが、ただ、ご本人の意向、それからご本人の状態にもよりますので、その辺についてまた、少し分析が必要かなと考えています。","voiceIndex":63,"id":"exchange-028"},{"speaker":"ゆきた副委員長","kind":"確認","question":"ここの実績を見ると、協定を結んでから１年少しで、実際、ここから区の福祉に結びついたものというのがあるのか、さらに具体的なところがあればお聞きできればと思います。併せてなのですけれど、データを統計では区でも公開されていますが、あなたのいばしょの担当者間で情報共有という定期的なものを行っているかというのも、ここも確認でお聞きできればと思います。","respondent":"東野福祉計画課長","answer":"詳細についてはお答えすることはできないのですけれども、例えば性的な暴力の関係があったりという部分ですとか、それからひきこもりの方について、区の支援が必要だというような問合せなどもありました。","voiceIndex":65,"id":"exchange-029"},{"speaker":"ゆきた副委員長","kind":"確認","question":"もう一点、区につなげるというものも確認させてもらったのですけれど、分析で見ると、土日夜間の相談が多いとか、先ほどの説明の中で、５０代が増えているということもあったと思うのですけれど、２０代での希死念慮が多いという分析結果もある中で、この時間帯に緊急性の高いケースが発生した場合というのは、区の緊急体制などのスムーズな連携ができるようになっているのか。","respondent":"東野福祉計画課長","answer":"具体的に、区のほうにこの方もう亡くなりそうだからということでつながれた事例はないのですけれども、区としては、何かそういうものの相談があったときに、どう体制を取れるか、また。","voiceIndex":67,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7277#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":33944,"voices":73}},{"id":"r07-20251127-10","meetingId":"r07-cm11","date":"2025年11月27日","dateIso":"2025-11-27","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7231#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1073,"voices":8}},{"id":"r07-20251127-20","meetingId":"r07-cm11","date":"2025年11月27日","dateIso":"2025-11-27","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"全体で、モデル事業も計画と同じ３年間という事業期間なのか伺います。この評価の高低による影響はあるのでしょうか。検討会は１０人でしたけれども、どのようなメンバーがいらっしゃるのかを教えていただきたいのと、あと、最後、都市型のウェルビーイングシティを目指してほしいという評価があったのですけれども、都市型のウェルビーイングシティとはどういうものなのか、伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"有識者の方ですが、１０名、大学の教授など有識者の方、例えば、ＳＤＧｓの先駆者とでも言うべき慶応大学の蟹江教授をはじめとする、東京大学ですとかのＳＤＧｓの分野で著作物なども出していらっしゃるような教授の方など、あとは。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"資料に基づいて具体的なところも少し伺いたいのですけれども、まず、１ページの付加価値額のご説明があったのですが、これ、単純にどのようにしてはかるのか、分からなかったので、はかり方を教えてください。なかなか苦戦していると思うのですけれども、もとよりなかなか本当に大変な課題だと思うのですが、これ、どのように目標値を達成する考えなのかについても、もう少し伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こちらにつきまして、所管でも当然、いじめの認知件数などについては、令和６年度から調査ツール、１人１台の端末を使って、より頻度高く調査を実施しているということがありまして、認知について強化してはありますが、この目標を目指すためにそこだけに集中するのではなくて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは要望です。これは２０１３年度比５０％目標となっているということでよろしいのか、確認したいのと、また、排出量の大部分を占める民生部門での削減と書いていますけれども、これがなかなか苦戦しているという、ここに省エネ機器の普及や環境意識の向上と書いてあるのですが、この加速だけでは私は達成できないと思うのですけれども、そこについてはいかがでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ここについて、記載の省エネ機器の普及や環境意識の向上、草の根の活動を含めた区民の意識の変容だったり、行動変容を促すような取組だったりを引き続き地道にするのが肝要かと、所管も含めて考えていますが、特に先ほど説明の中でも申し上げましたように。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"２０３０年はあっという間に来てしまうと思うのです。なので、ぜひこの分野においては、目標達成のための手段として、進捗状況や課題等にも書いておりますが、ぜひ私は超高層ビル開発規制も検討すべきだと思うのですけれども、それについては、お考えはいかがでしょうか。要望したいと思うのです。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区としましては、広く事業部門、家庭部門のＣＯ２の削減の目標量を、達成に向けて区民の方への周知啓発、それから、事業者の方への啓発、多様なステークホルダーを巻き込んで進めていくところですので、特定の再開発について何か取組をする考えはございません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"ただ、ＳＤＧｓのこの部隊は、やはり司令塔なわけですから、そこで全体として目標達成のために何が必要かという、大所高所から私は見ていく必要があると思うし、それに対して必要であれば規制などをかけていくとか、そういうことをできるのは、やはり私はＳＤＧｓの部隊だと思いますので、ぜひ全体から見て、まちづくりの在り方も含めて、必要な手を打っていただく必要があると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"兆単位ということですか。兆単位で目標値を既に達成しているということで、これは要するに、先ほどのお話から伺うと、区内の企業がかなり利益を得ているということでいいのかどうか、その辺りの考え方をまず教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"自治体は地域のインフラ整備に対して極めて大きな役割を有していると考えておりますので、付加価値額については、９番、それから、ターゲットについては、９番、９の２ですので、包括的かつ持続可能な産業化を促進し。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"ということは、先ほどのＳＤＧｓのゴールとターゲットにおいて、品川区に立地をしている事業所単位では、私の感覚で言えば、目標をはるかに超えていて、いわゆるすごく利益が出ている、これはＳＤＧｓの目標に資するということで、非常に兆という金額がすごくインパクトがあったものですから、東京都全体で約１５６兆円ということの中の約４兆円なのですけれども、本当にすばらしいと、普通に素直に思います。","respondent":"井添ＳＤＧｓ推進担当課長、崎村企画課長","answer":"進捗評価と併せて、こういったＫＰＩの設定そのものについても効果検証を進めながら、例えば、次、令和９年度からの第２期の計画の改定の時期などに合わせて、指標の大きな見直し等も併せて検討していければと考えております。区の転入が特に多いゾーンとしては、やはり１５歳から２９歳、こちらの年齢層が男女共、転入超過という状況でございまして、転入を世帯別に見てみますと、転入される方の９割が単身の方で。","voiceIndex":17,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３６％でしたか、いらっしゃるというようなこともあって、そこをお伺いしたいのですけれども、いわゆるこの指標の中に、そういった視点を大きく入れていく必要があると。その辺り、何かあれば、教えていただきたい。その辺りの方のやはり満足度とか何かをはかっていく必要、要望、ニーズがどこにあって、これからどういう目標を達成していくのか、ぜひそういったことをお願いしたいということが１つです。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こちらについては、引き続き所管も含めて、今後どういった計画の、来年度どの程度の改定や指標の評価などが認められるのかは、内閣府との調整になってまいりますが、今回の進捗評価の結果を受けて、また所管とともに検討を進めていきたいと考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"そういう意味では、計画に基づいて、モデル事業のテーマに基づいて、品川区は堅調に、所管の本当にご努力と、あとは区の方針として、非常にそこに力を入れていらっしゃると感じましたので、ぜひ今後とも慎重に続けていただければと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"これから、今まで質疑の中で、目標の設定の考え方も変えていく、検討していくともありましたので、その見せ方については大いにしっかり工夫をしていただきたいというのが１点と、もう１点が、２０３０年、目標が目前でありますけれども、２０３０年を見据えた、今後のその次の、２０３０年以降の品川区の目標の在り方といいますか、その辺についてのお考え、検討というのは、２０３０年を超えた後。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"なので、２０３０年の時点で目標に達成しなかったらそこで終わりではなくて、引き続き今の取組自体は、そして、ＳＤＧｓがポストＳＤＧｓとかに変わる可能性はもちろん、国連の動きとかで変わってくるかもしれませんが、今の方向性自体は大きく変わらないと思いますし。","voiceIndex":24,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後の２０３０年までの取組、それ以降の取組につきましては、またちょうど品川区の長期基本計画も策定が２０２９年と一つの区切りがあると思いますので、しっかり長期基本計画にも合わせていけるように、また取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"なので、そこら辺の指数の入れ方は、これからやっていくという話だったので、そういった部分はいろいろと検討していただきたいと思います。それと、あと、中小企業でやはりなかなか啓発が難航している部分、脱炭素、そういう話もありますけれども、具体的に何が障壁となっているのですか。壁となっている部分、それをまず教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こちら、環境課とも相談する中で、やはりただ啓発、ＳＤＧｓですとかゼロカーボンについて、環境に優しいとかそういったところではなくて、実際に中小企業の方にとって、例えば、電気料金の削減であったりとか、あとは、企業にとってメリットになったり。","voiceIndex":28,"id":"exchange-012"},{"speaker":"まつざわ委員","kind":"質問","question":"例えば、今、シティラボをやっていただいていて、いい取組をやっているのですから、そういうのを活用して、五反田バレーなどが照明とか、電気制御などをやっている。そういった技術を中小の工場に一緒に結びつける。コラボさせるのです。こういう事業を区がハブになってやっていく、そういった取組を進めていくといいと、素人ながらにすごく思ったのですけれども、どうなのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"この夏に実施して、電気量の削減に一定の効果が見られ、やはり夏と冬と、また次の夏と実証をして、データをきちんと分析をする必要があるということで、しばらく実証実験を続けていくところではありますが、こういった効果が出れば、区内の中小企業をはじめとする事業者の方に。","voiceIndex":30,"id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そんなすばらしい取組があったなんて知らなかった。ぜひそういった観点から、どんどんマッチングさせて、組み合わせて、ＳＤＧｓ推進に向けて、今も大分頑張っていただいていますけれども、さらに頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"進捗に対する理解が深まりました。私からも何点か質問します。その計画の中身と、あと、運用について課題があれば、教えていただきたいと思います。それから、このご説明の中で、特に堅調に推移している指標と、当初値から改善されていない項目とを抜き出してご説明をしていただきましたけれども、この抜き出した基準とかがあれば、教えていただきたいと思います。お願いします。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"一方で、課題ですが、これまで委員の方からもご指摘、ご意見、ご提案がございましたように、この成果であったり、また、取組自体であったりを、区民の方に広く周知していく、ご説明していくといったことについては、まだまだ取組が十分ではないと認識しておりますので。","voiceIndex":34,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"区としてのご認識、理解をいたしました、ぜひ見える化、立ち位置を確認しながら次の手を打つということで進めていただきたいと考えています。課題も、発信、工夫をしていただきたい。社会、経済、環境ごとに、表で項目別に指標を見ると、全体でどうなるか、より伝わりやすい、より分かりやすくなると思いますので、次回のご説明のときには、そういったところもぜひ作っていただきたいと思います。要望です。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今後のＳＤＧｓの達成状況等の見せ方について、全体感というか、定量的に示していく、棒グラフなどで視覚的に分かりやすく、三側面ごとに伝えていくことについてのご提案は、今後検討してまいりたいと考えております。","voiceIndex":38,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"既にほかの委員からの質問で説明いただいたところは除いて質問するのですけれども、まず、児童・生徒の不登校出現率の確認ですけれども、出現率を下げるための取組として、フリースクール等の受皿の拡大と書かれておりますので、それはつまり、フリースクールに通うことで、不登校ではなくしていくお取組を進めていくということでしょうか、それは何かというと。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"委員からご提案として、東京都が実施しているような結婚のマッチングなどについて区として取り組む考えはあるのかというご質問でございましたが、区としては、現在実施しているような子育て支援策について、例えば産みやすい環境で、産後ケアの拡充ですとか、充実ですとか。","voiceIndex":40,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"健康ポイントについては、ぜひ併せてご確認と改善を進めていただきたいと思います。それと同時に、日頃からＳＤＧｓを意識した行動を取っているかどうかについて確認する、意識調査にそういう今後確認する項目を入れないと、これが確認できないので、ぜひ行動変容につなげることを目標に掲げているとすると、この項目も大田区のように追加していただくことをご検討いただきたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ＳＤＧｓに日頃から取り組んでいるのかという大きな質問ではなくて、例えば、マイボトルを持つように心がけているかとか、プラスチックをなるべく使わないようにしているかというような、そういった具体的な項目という形で。","voiceIndex":42,"id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"最後の浸透度をはかるところについては、そのように個別の行動についてのご質問があるということで、それでぜひ確認を進めていただき、その意識を高める取組を併せて進めていただきたいと思います。それぞれいろいろとよく進めていただいていると思いますので、ぜひさらにＳＤＧｓの取組を前に進めていただけるよう、どうぞよろしくお願いいたします。期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"それで、質問といたしましては、ミドル期シングルについて、先ほどあくつ委員からのご質問もありましたけれども、３５歳から６４歳の方のミドル期で独身の方ですが、品川区のＳＤＧｓ未来都市計画の中で、孤独・孤立対策も書かれておりますけれども、ミドル期シングルの方が全員孤独・孤立を感じているわけではないのですが、ＳＤＧｓ未来都市計画の中で孤独・孤立が子どもの箇所に書いてあって。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、ＳＤＧｓの理念といたしまして、誰一人取り残さないというところがありますので、子どもに限らず、全ての世代に対して、区としても各取組を進めていますので、ミドル期シングル含めて、今後の計画の策定、計画改定に当たっては検討してまいりたいと考えております。","voiceIndex":46,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"ご事情は理解いたしました。２０２４年時点で、東京２３区内で出生率１.１を超えたのが、千代田区、中央区、港区の３区だけで、千代田区、中央区、港区は、高所得者層が多いエリアです。なかなかつながっていないのが現状と思うのですけれども、私が言いたいのは、出生率向上のためのインプット・活動に、やはり経済的な側面も入れたほうがいいと思ったのですけれども、その辺り、いかがお考えでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"現状、区としては、先ほどもご説明させていただきましたように、子育て支援策のさらなる充実で、最終的な出生数の増加、合計特殊出生率の上昇といったところに寄与できればと考えておりますが、ご意見をいただきましたので、そちらも受け止めさせていただければと思います。","voiceIndex":48,"id":"exchange-021"},{"speaker":"筒井委員","kind":"意見","question":"出会う場を増やすのも、やはり時間的な余裕もなければいけないので、そして、経済、プラス時間的余裕をつくる取組も必要と思っていますので、非常にそれはなかなか難しい課題ですけれども、取り組んでいかなければいけないと思っていますので、ぜひよろしくお願いしたいと思うので、その辺、何かお答えいただければ。どう考えられるのか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"結婚に対する施策を区としても打つべきというようなご提案ですが、今回のＳＤＧｓの合計特殊出生率に向けては、子育て支援策をさらに充実をして、ＫＰＩが上昇していくのかどうかという推移を引き続き区としては確認をしてまいりたいと考えていまして。","voiceIndex":50,"id":"exchange-022"},{"speaker":"こしば委員","kind":"質問・要望","question":"それをいかに解消していくかが大切なことで、子どもたちの安心につながってくると思いますので、そこは本当に間違うことは当然ないとは思うのですけれども、所管と連携をしていただきたいと思います。その辺り、課長のお考えをお聞かせいただきたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"所管とも確認する中で、出てこないいじめがあることが、認知できないといった状況が一番ゆゆしきことだと思いますので、１人１台の端末などで少しでも気軽に、まだいじめにつながっていないケースも含めて、学校で把握できるといった取組を引き続き強化していくとともに。","voiceIndex":53,"id":"exchange-023"},{"speaker":"こしば委員","kind":"質問・要望","question":"もう１つは、合計特殊出生率、こちら、先ほど来お話がされておりますけれども、これも数値でいったら、まだまだなところはあるかもしれませんが、出生率を上げる、大変国力を上げることにつながるかもしれませんけれども、また、一方で、母親の教育の手から離れてしまった子どもたち、特別養子縁組、様々なものがありますけれども、そういったものは確かに出生率とは、生まれているわけですから。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こういった合計特殊出生率には見えてこない、ご指摘のとおり、子どもたちを誰一人取り残さない環境で、きちんとした居場所ですとか、区として地域で子どもを育てていくということについては、引き続き取り組んでまいりたいと考えております。","voiceIndex":55,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7233#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":34728,"voices":61}},{"id":"r07-20251128-22","meetingId":"r07-cm11","date":"2025年11月28日","dateIso":"2025-11-28","committee":"まちづくり・公共交通推進特別委員会","time":"午前１０時００分～午前１１時２５分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ご説明、ありがとうあります。幾つか確認も含めて伺いたいです。ＪＲがやることなのでしょうけれども、どんな状況でどういうまちびらきになるか、品川区が関わるのかということを伺いたいです。２ページの1)の広域避難場所の開放とあるのですけれども、広域避難場所というのはどこでしたかという確認をさせていただきたいです。そこまでお願いいたします。","respondent":"泉広町事業調整担当課長","answer":"けれども、やはり地域一体となったにぎわいの創出といったところがこのまちづくりの目的の一つでもありますので、そういったまちびらきにあたりましては、地域と何かしらの関連性を持って地区一帯が盛り上がるような取組を進めてまいりたいというところで考えているです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、広域避難場所はこの地図でいうと書かれていない部分ということですか。","respondent":"泉広町事業調整担当課長","answer":"大変失礼いたしました。広域避難場所は、今１ページ目でお示しをしている広町地区のまちづくりの着色がしてあるところにつきましても、基本的にはそこも指定がかかってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"提案","question":"分かりました。次に行きます。それから、(2)で、公園と現庁舎跡地を活用した具体的な提案はほとんど見られなかったということだったのですけれども、なぜ公園と庁舎跡地を活用した具体的な提案がほとんど見られなかったのか、理由を聞いているなら伺いたいです。そうすると、１ページ目の地図でいうＢ－２、Ｂ－３の街区が建物としてつながるというイメージなのでしょうか。そこまで伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"民間事業者のほうも民間事業者としての収益性を確保するような施設も必要であるけれども、こういった今回の庁舎跡地等活用検討委員会で話されました活用のテーマみたいなところもお示しした上でサウンディング調査を図ってあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"提案","question":"それと、５ページにある公園と現庁舎跡地を活用した具体的な提案がほとんど見られなかったというところでは、違った事業手法になってくるということです。引き続き伺っていきたいのですけれども、６ページの大きい３番の活用方法の続きのところで、Ｂ－２街区の国と区の共有地が存在しているということですけれども、これを区が所有するということは、国と都が賃貸になっていくということなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"導入機能につきましては、来年度活用プランを策定する中で議論を深めてまいりたいというふうに考えてありますけれども、いずれにしましても当該地区のまちづくり方針の中で、にぎわいのゾーンになっている、また。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういう方向、検討状況等をご報告いただいているところですけれども、私たちとしては本当にこの場所は区民の貴重な財産だと考えておりますので、こうした土地を区民のニーズに全面的に使っていくということを求めておきたいと思います。続いて、区画道路整備について、伺いたいと思います。補助２６号線を通る東急バスがここに入ってくるというふうに考えればいいということなのでしょうかという確認です。","respondent":"泉広町事業調整担当課長","answer":"今後のスケジュールの中の活用プランの策定の委員会についてですけれども、委員会につきましては区議会議員の皆様に入っていただくような方向性を持って今は庁内で調整を図っているところで、具体的な人数につきましては現在検討中で、まだお知らせできる段階でないものですから。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いずれにしても、こうした区の庁舎の跡地活用ということで、区民の貴重な財産がどのように使われていくのかというところを区民の皆さんもすごく期待とともに心配もしています。なので、共産党としては本当にみどり豊かで一息つけるような空間とともに、区民の求める施設等の整備が大きく進む活用になるように、引き続き求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"ご説明、ありがとうございました。その上で、何点かお伺いをしたいです。順番に申し上げると、最初の災害時協力協定の関係ですが、これはあくまでも個人的な意見というか思いですけれども、帰宅困難者対策というのは、大都市事務だと思っておりまして、本来であれば区よりも東京都が広域的に対応すべき課題だと、今の時点で思っております。東日本大震災のときには出ました。そこをお伺いしたいと思います。","respondent":"遠藤防災体制整備担当課長","answer":"参考までに、現在大井町駅周辺の帰宅困難者対策で受け入れられる一時滞在施設の人数は、およそ３,１００人となってございまして、ＯＩＭＡＣＨＩ ＴＲＡＣＫＳができても１万人程度不足するところで、さらに一時滞在施設のスペースの確保というところが求められている状況です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。先ほどのご質疑を伺っていますと、跡地活用に関する学識経験者へのヒアリングのところでみどりの整備ということが書かれています。そういうところまで踏まえて、学識経験者の方はみどりのネットワークを形成と言っているということなのか、学識経験者の思いがどういうところにあったのかということをぜひお伺いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"庁舎跡地等活用検討委員会の中でも、みどりの充実を求める声があったというところがあります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"この図を見ると、何となく少し黒っぽく書かれているスペースがあるのですけれども、そこにバス停ができるのかどうかというのは分からないのですが、今後東急バスとの交渉もあるとは思いますけれども、新庁舎建設時においてのバスのロータリーまでは分かるのですが、その手前のバス停の設置に対して私はぜひ区としては求めていただきたいと思います。今の時点でのご見解をお聞かせいただきたいと思います。","respondent":"泉広町事業調整担当課長","answer":"一方で、今委員からいただいたような交通利便性の向上の観点で、そういったバス停の充実といいますか、そういうところにつきましては区といたしましてもバス事業者のほうと会話を重ねてまいりたいと思ってありますので、かなえられるかどうかというところにつきましては。","voiceIndex":21,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"別紙２の３ページのこれまでの検討状況で、真ん中に四角で囲っている区の中心核としてのシビックコアを形成するとともに、大井町、大崎都市軸の拠点形成を図るとあります。これは大崎の跡地の利活用とどういう連携をしているのか。都市軸という言葉に込められている思い、あとは拠点形成とか、このことについてもう少し詳しくお考えをお聞かせいただきたいと思います。","respondent":"高梨都市計画課長、泉広町事業調整担当課長","answer":"私からは、都市軸等についてお答えをします。Ｂ－３街区に少し分けて書いてありますのは、Ｂ－３街区には住宅の機能は付与せずに、にぎわいですとか集客機能といったところに特化をする形が望ましいのではないかというような意見が見られたというところと。","voiceIndex":24,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。これは大事なことだと思いますので、ぜひしっかり検討していただきたいと思います。現在の建設費や不動産市況の継続が前提であるということについて教えていただきたいと思います。まだ物価とかいろいろな建設費がかなり上がっていくのだろうということが一般の予測だとは思うのですけれども、継続と言っていることの意味をもう少し詳しく教えていただければと思います。","respondent":"泉広町事業調整担当課長","answer":"５ページ目に記載があります現在の建設費、不動産市況の継続が前提と書いてありますのは、今委員からご指摘ございましたとおり、今の建設費がそのまま募集の段階も同じだった場合には２００億円の負担が一定程度できるのではないかというところのご提案があったということなので。","voiceIndex":29,"id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"やはり、そうなのですね。現時点の条件の継続ということですね。現実的には、何％くらいまでを許容範囲とするのかなど、多分いろいろあるのでしょう。ここは不安というか懸念要素だということで、かなり今後の各企業さんの判断に影響を与えるところだということを今認識いたしました。その点については今後ともまた注視していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"ご説明、ありがとうあります。今、塚本委員からもご質問がありましたが、庁舎跡地活用に関する対応型市場調査についてです。Ｂ－２街区には住宅機能、Ｂ－３街区には住宅機能を入れないという認識でよろしいでしょうか。","respondent":"泉広町事業調整担当課長","answer":"具体に導入してまいります機能は、また来年度から策定してまいります活用プランの策定の中で議論をしてまいりたいと思ってありますけれども、今私のほうでご説明した対話型市場調査の提案の中では、Ｂ－３街区のほうにも住宅を入れる案と入れない案ということで。","voiceIndex":32,"id":"exchange-013"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。民間のノウハウ、民間の活力を最大限に活用したまちづくりということで、商業やにぎわい、集客機能等、公益性の高い複合施設を導入ということですけれども、既に集客する起爆剤となるような収益モデルとかというのはアイデアとして出ているのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"事業収支の見立てといったところですけれども、対話型市場調査の中では民間事業者も検討の深さに差がございまして、検討がかなり進んでいるところとそうではないところといろいろあったところです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"えのした委員","kind":"確認","question":"ご説明、ありがとうあります。なかなか収益の部分は、どの企業にとっても難しいところなのかなという確認が取れました。先ほど、田中委員のほうからも防災協定のご質問がございました。想定最大が１万６,０００人、現状は大井町周辺が３,１００人で新たに協定を結んでも１万人不足している。正式名称は東日本旅客鉄道株式会社と言うのでしょうか。その辺を詳しく教えていただけますか。","respondent":"遠藤防災体制整備担当課長","answer":"ＪＲ東日本のほうで備えている災害時の備蓄品、例えば災害用トイレ、公共無線ＬＡＮ、あるいはスマートフォン向けの充電といったところのサービスに関しましては、ＪＲ東日本から支援を受けて帰宅困難者に提供していくといったスキームになってあります。","voiceIndex":36,"id":"exchange-015"},{"speaker":"えのした委員","kind":"確認","question":"ご説明、ありがとうあります。３,０００人分を１,５００人ずつということで、確認が取れました。一時滞在施設、帰宅困難者対策ということですけれども、地域だと避難所開設を地域の町会とかが受け持ってやることになっておりますが、こちらの協定には避難者等の誘導なんていうものが入っております。区としても参集職員を何名か確保していくのか。その辺をお聞かせください。","respondent":"遠藤防災体制整備担当課長","answer":"ただし、区としても帰宅困難者対策を民間事業者の方が円滑に運営できるように、定期的に帰宅困難者協議会に対するサポートとして訓練の支援ですとか、あるいは東京都のほうで発信している帰宅困難者対策のシステム、キタコンＤＸもありますが。","voiceIndex":38,"id":"exchange-016"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"２００億の話を出したら、良い提案が出るわけがないだろうと思います。そういうこともあるのではないですか。これの何がにぎわいなのでしょうか。２００億円という話を１回消さなければ、いい提案が出るわけがないです。Ｂ－１だって向こうに庁舎は建てるけれども、こっちは低層階ではないですか。そういう提案もありましたと、分かっているではないですか。やれるのはＢ－２しかないのですから。","respondent":"泉広町事業調整担当課長","answer":"様々なご意見、ありがとうございました。２００億円の受け止めです。我々は、新庁舎の整備にかかる経費負担を少しでも軽減したいという思いから、２００億円といった一定の金額を出してまいりました。","voiceIndex":41,"id":"exchange-017"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"もうこれでやめますけれども、広町事業調整担当課長には前にもそんな話をしました。本当にすみません。課長に言ってもそういう答弁が来ると思います。私はいろいろな会があったときには必ずこれを言っていきます。それだけは、言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-018"}]},{"id":"topic-02","title":"新庁舎整備に向けた工事説明会の実施結果","agenda":"新庁舎整備に向けた工事説明会の実施結果","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"確認ですけれども、２４番の意見、食堂の設置についてということで、区の回答としては、飲食施設として、３階にカフェがありますとあるのですが、このカフェは障害者カフェですか。そこで、食事もできるということですか。食堂の代替になるようなカフェだということでいいのでしょうか。","respondent":"小林新庁舎建設担当課長","answer":"食堂で飲食ができるかできないかということと、カフェの内容とかありますが、従来からご説明しておりますとおり、３階には障害者就労を目的としたカフェを整備することで計画を進めてあります。","voiceIndex":48,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"食堂を希望する方の声がちらほら聞かれます。ですので、やはり区役所の中に食堂というものがあったほうがいいのではないかと私も思っています。こういう質問が出た中で区がこういう回答をしていましたので、軽食程度かもしれないということですけれども、こうしたところでも食事ができる施設になるといいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"工事の内容にもよるのでどこまで立ち入ってということはあるのですが、恐らく地域の飲食店側からすると、通常のこの周辺に勤務されている方の休み時間も１２時から１３時の中で、少しずらすと逆に飲食店の方にとってもメリットもあるのかと勝手な想像でもあるのですけれども、そういうご配慮というか、具体的に何時から何時にしてくださいとも一方で言いづらい話ではあるのですが。","respondent":"小林新庁舎建設担当課長","answer":"作業員の皆さんのいわゆる働く時間の制限ができるかどうかということつきまして、やはり発注者側のほうから何かこうしなさいという指示はなかなかできないのかなと思います。","voiceIndex":52,"id":"exchange-021"}]},{"id":"topic-03","title":"路線バスのバス停新設","agenda":"路線バスのバス停新設","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"１月１６日ということで、日にちが明確に示されまして、本当に地元では結構スペースがあるのにどうして片側ができないのかということで、かなりご要望をいただいていましたので、大変によかったと思います。お聞きしたいのは、関連になってしまうのですけれども、平塚たけのこ公園バス停についてです。こちらは、今は片側のみです。せっかくのこういった機会ですので、現状をお聞かせいただければと思います。","respondent":"櫻木地域交通政策課長","answer":"ご指摘のバス停につきましては、東急バスのほうも精力的に働きかけ等を行ってきている状況ではありますが、委員ご指摘のとおり課題がまだ残っているという状況で、もう少し時間がかかるというふうに聞いております。","voiceIndex":59,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この辺のバスで１０時半より前の時間帯のバスがないところもあるというふうにも聞いておりまして、運転士不足等もあると思うのですけれども、そうしたところの要望も区のほうには届いているのでしょうか。そして、それは東急のほうと何か議論をされているのでしょうか。お聞かせください。","respondent":"櫻木地域交通政策課長","answer":"バス停の屋根の設置ですが、単純にバス停を建てるのと屋根をつくるのでは、建物をつくるという形にもなりますので、費用的にも大きく異なってくるということで、東急側のほうとしても費用面、ご要望等も含めて判断していくということになろうかと考えています。","voiceIndex":62,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"確かに、屋根は新たに建てるとなれば費用がかかってくると思うのですけれども、やはり利用する方の状況からすればバス停で待つということは多々あると思うので、利便性や利用率を向上させていくというところでは、こうしたこともぜひ引き続き求めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7279#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":27231,"voices":71}},{"id":"r07-20251204-10","meetingId":"r07-cm12","date":"2025年12月4日","dateIso":"2025-12-04","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年陳情第５４号、予算・決算委員会や常任委員会等のライブ配信とアーカイブ動画公開を求める陳情","agenda":"令和７年陳情第５４号、予算・決算委員会や常任委員会等のライブ配信とアーカイブ動画公開を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"具体的に伺いたいのですが、委員会のネット中継、アーカイブ配信を行うということについては、時期はどうあれ、ここで全ての会派で一致できるのか、確認させていただきたいのです。私たちは必要だと、行うべきだと思っているのですが、皆さんのご意見を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"これは議会運営委員会に付託されているので、議会運営委員会としてはどう考えるかというところが大事だと思うのです。ただ、今のお話だと、検討が必要だというところで皆さん一致されたので、検討は必要だということで、これは採択ということで、皆さんよろしいということですよね。私はそう判断しましたが、皆さん、どうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"意見","question":"今、声かけがあったのでお答えをしたのですが、どうも誤ってご理解をされていらっしゃる。では、必要だから採択をすると、何でそんなに論理が飛ぶのか、少し理解し難いのですが、というところだけは申し上げておきます。議論はできないので、それだけは申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"どういう態度が出てくるのかというのはこれからなのかもしれませんけれども、私はそういうふうに理解したのですが、まさかこれで不採択とはならないだろうなと理解したのです。それで、事務局にもお伺いしたいのですが、現在把握している範囲でいいのですが、他区の委員会の動画配信状況はどうなのか、伺いたいと思います。","respondent":"大澤区議会事務局長","answer":"２３区の中で、現在、委員会のライブ配信をしている区は５区です。","voiceIndex":19,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"目黒区も同様でした。港区も同様でした。この陳情にもあるように、実績として４０名を超える、定員を超える傍聴があり、傍聴者が入れない、聞けないという弊害もありました。やはり私はすぐにでも始めるべきだと思うので、ぜひこれを採択すべきだと、採択してすぐにでも始めていく努力が品川区議会に求められているということを、意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-005"},{"speaker":"せお委員","kind":"意見","question":"先ほどほかの会派からもあったように、検討とか議論をする必要は今後あると思うのですけれども、例えば方法ですとか、そういったところも含めて検討していきながらということなので、すぐに始めるというのはかなり難しいことだと思いますし、新庁舎もこれから建設していくということで、新庁舎ということを頭に入れて検討していかなければいけないのではないかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-006"},{"speaker":"松永委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。以上の財政的課題を考慮し、本陳情に対しては不採択といたします。一方で、開かれた議会の実現に向けた取組として、今後予定されている新庁舎の建設においては、これらの機材やインフラを効率的に整備できるように、また、全委員会室へのカメラの設置等につきましても、要望していきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出すで、不採択です。以前にも、全くイコールではないですけれども、同じようなライブ配信のことでのご要望もいただいたかと思いますが、先ほどほかの会派からもありましたとおり、これからあと４年後、令和１１年度に新庁舎ができるという中で、そういった検討をするタイミングは来ているということは、皆さんも感じていらっしゃるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"早急に改善すべきだと思いますし、こういった区民の方から、非常に積極的に議会に関わっておられる方から、こうした積極的な陳情が出たということに対して、議会がこれを否決して先延ばしにするということは、私はそれでいいのかな、それで品川区議会の議会改革は大丈夫というか、それで情けなくないのかなと私はすごく思いますので、二重投資とかという話もありましたが、民主主義のコストで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-009"}]},{"id":"topic-02","title":"令和７年第４回定例会","agenda":"令和７年第４回定例会","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、委員長からもお話がありましたように、自民党で議案の形でまとめさせていただきました。多様な人材の地方議会への参画促進を求める意見書ということで、提出者になっていただけるという方は、記載のとおりです。説明については、案文の朗読をもって代えさせていただきたいと考えていますので、今、案文を朗読します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"地方議会に関心を持ってもらうことや、地方議員になりたいと考える方々を増やして、多様な人材に議会に参画してもらうことは重要なことだと思っています。その上で質問ですが、前回、案が出されました。議運に所属しない会派ですとか無所属の方を含めて、この案に対しての意見を伺っていくということだったと思いますけれども、どのような意見が出たのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-011"},{"speaker":"安藤委員","kind":"提案","question":"この項目２の最後の部分、「厚生年金へ」というところ、これ以降の部分を削除する修正を行うべきなのではないかなと思うのですが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"これについては、ここにも書いてあるとおり、様々な方、会社員の方は厚生年金へ入っていたりもするわけでしょうから、そういう様々な方が立候補して休暇を取る、そのときに国民年金なのかということではなく、そこは様々な形で厚生年金の加入もできるように、そういう法整備も必要だろうということで、これは全国市議会議長会からもそういう幅をどんどん広げてほしいというお話があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。なので、多数で決めてしまうというやり方はやるべきではないなと思っていまして、そういった観点から、継続して議論を続ける努力をすべきだと思うのです。明日の本会議には提出しないと。その上で議論を続けると、そういった判断が必要なのではないかなと思うのですが、それは誰になるのでしょうか。そういった判断をしていただきたいのですが、皆さんなのか、委員長なのか、自民党なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"我々としては、これは今日、こういうふうに皆さんにご提示しているわけですから、明日、議案にしていただいて、多数でも決定をして、意見書を提出していく。ここに書いてあるとおり、そこへ提出をしていくということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"繰り返しになってしまうのですが、やはり議員の待遇に関わる、一人一人の議員に関わることなので、私は、拙速に、一部の人が賛同できるからということでやるのではなく、１０人ぐらいは提出者になっていないわけですよね。ですから、全会派でもないわけなので、丁寧に議論すべきだということを改めて意見として述べさせていただきたいと、強く述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"}]},{"id":"topic-03","title":"令和８年第１回定例会","agenda":"令和８年第１回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"日程について、私たちは、民生費のところを分割して日程を増やしてほしいという意見を言ってきたのですが、しかるべき会議体で議論をしたいというお話を何度かいただいたのですが、この間、開かれるということになったと伺ったのですが、ぜひその場でも私たちも意見、提案はしたいと思うのですけれども、ぜひそういった場で検討されることを願っておりますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7235#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":12087,"voices":72}},{"id":"r07-20251225-6","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"区民委員会","time":"午前１０時０５分～午前１０時２２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出等 区民委員会所管分）","agenda":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出等 区民委員会所管分）","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"それで今、説明の中で分からなかったことがあったのでお聞きしたいのですけれども、一つは、コールセンターの経費に１億６,０００万円ほどかかっているのですけれども、プッシュ型なので、申請は要りませんという説明があったのですけれども、大抵、問合せだと、申請に関する問合せがこれまであったと思うのですけれども、申請不要にもかかわらず。","respondent":"今井八潮まちづくり担当課長","answer":"２点ご質問いただきました。コールセンターの設置の理由ですけれども、こちらについては、前回のしながわ活力応援給付金事業の際に、コールセンターの問合せ数が約１万６,０００件あったということで認識しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"こしば委員","kind":"質問・要望","question":"コールセンターの質問の内容などは分かったのですけれども、ギフトカードが使える期間が、送られてから半年程度という説明だったのですけれども、つまり半年間、コールセンターを設置していく考えなのか、もしくはその状況を見ながら、２か月、３か月か分かりませんけれども、早い段階で一旦コールセンターを立ち上げるということもあり得るのかどうか、その辺の考えを教えていただきたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"基本的には、コールセンターについては、ギフトカードの郵送前に設置する予定ということで、春以降にギフトカードを配布するのに先駆けまして、その１か月前ですとか、ある程度十分な期間を設定して、ギフトカードが区民の皆様のお手元に届く前に。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"ギフトカードですが、今検討中ということで、クオカード等の民間のものから、いろいろなものを検討されていると思いますが、印刷したりとかそういったことも視野に入れているのでしょうかというところと、なるべく広くということで、特に区内の事業者やお店、商店街が活性化するような、そういったものは特に考えず、単純に皆さんに使っていただくということが今回、主目的になっているのかという部分。","respondent":"今井八潮まちづくり担当課長","answer":"カードの内容については、検討中というところで、どんな内容になるのかというところは、これから決定していくところではあるのですけれども、新規にカードを発行するですとか、印刷するとなると、その分、事務的な経費もかかりますし。","voiceIndex":10,"id":"exchange-003"},{"speaker":"おぎの委員","kind":"確認","question":"分かりました。本当に物価高対策というか、そういった生活支援というのが主目的だということを確認いたしました。もう一点、郵送でプッシュ型というので、一番事務経費を抑える形だとは思いますが、これは一応、金券になるのですが、郵送はどういった形を想定していますでしょうか。普通郵便なのか、簡易書留等なのか。","respondent":"今井八潮まちづくり担当課長","answer":"郵送につきましては一定、配送記録の残るものということで予定しておりまして、例を挙げますと、簡易書留ですとか、ゆうパックですとか、そういったお届けをしましたという記録が残るもので郵送する予定です。","voiceIndex":12,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"他区だと、独自のポイントとか、区内共通商品券とかにするところもあるようですけれども、品川区でも区内共通商品券という検討はあったのかというのもお聞かせいただきたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"所管のほうで、プレミアム付区内共通商品券につきましても今回、配布対象にするかどうか検討はさせていただいたところではありますけれども、今回の事業については、やはり区民への配布の迅速性というところ、あとは４２万枚を調達するといったところで。","voiceIndex":16,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それはこれから検討ということなのだけれども、この辺は十二分に検討していただいて、迅速に配布できることを考えなければいけないので、そこはいろいろ検討していっていただきたいと思います。それとあと、これは要望なのですけれども、こういうことになると、区の職員を装った詐欺というのは必ず出てくると思うので、その辺、発行のときには注意喚起をぜひやっていただいて、対応をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7287#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":5574,"voices":27}},{"id":"r07-20251225-9","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"文教委員会","time":"午前１０時０５分～午前１０時４２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"幾つか確認させていただきたいのですが、支給対象者のところで、９月３０日時点を基準にした理由を伺います。公務員が別で出ているのですけれども、公務員は仕組みが何か違うのでしょうか。児童手当の認定を受けてない新生児の方が２,０００人と、公務員は４,０００人の児童がいるということですが、申請が必要な方はどんな方になるのか、いつ頃生まれた方なのか伺います。","respondent":"柏木子育て応援課長","answer":"初めに９月３０日時点の基準ですが、こちらは国が示している基準日になってあります。公務員につきましては、所属庁、自分の勤め先から給与と一緒に児童手当が支給されています。ですので、子育て応援課では、公務員の方については把握ができない状況です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"９月３０日時点を基準として、国が示した理由などがもし分かれば伺いたいと思います。公務員は、そうすると申請が必要なのですか。そこはプッシュ型ではなくて、申請が必要ということになると、漏れがないようにお願いしたいのですけれども、その点が大丈夫なのか伺います。そうしたことへの対応をしっかりとしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"柏木子育て応援課長","answer":"最後にＤＶの対応ですが、こちらは今、児童手当につきましても、そこら辺の対応はきっちりしておりますので、今回の物価高対応子育て応援手当につきましても、同様にしっかりと対応していきたいと考えています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"最後に公務員について、そうすると所属しているところから証明書が出されて、それを住んでいる自治体に提出する形になるのですか。その仕組みを伺います。","respondent":"柏木子育て応援課長","answer":"委員、今お話しされたとおり、証明書を持って、お住まいの役所に提出いただくことになります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"確認も含めてですけれども、申請を要する方は、新生児の方という想定でよろしいのでしょうか。例えばほかにどういった方が今回、新たに申請しなければならないのかを、区としてどのように想定しているのか確認させてください。２点目ですけれども、区民への周知で、児童手当受給者へ通知を送付するとあるのですけれども、こちらはいつ頃の送付を予定しているのでしょうか。時期を教えてください。","respondent":"柏木子育て応援課長","answer":"それと児童手当の対象だけれども、児童手当を受給されてない方、それぞれ理由があると思いますけれども、その方で今回、物価高対応子育て応援手当については支給してほしいという場合は申請が必要になります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つは、児童手当受給者ですが、これは児童手当の支給が今度、１２月になるのでしょうか、そのときに同時になのか、それとも次の児童手当の支給のときになのか、それともこの手当だけを支給するのか。２つ目は、９月３０日以降に品川区に転入した方、例えば１２月に転入してきた方は、前に住んでいたところに申請することになるのですか。","respondent":"柏木子育て応援課長","answer":"最後の繰越明許費の件ですが、こちらは３月３１日までに生まれた方ですので、５月末までには支給が完了するという形になります。繰越明許費につきましては、物価高対応子育て応援手当についてはしないです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"コールセンターの話は、この事業が始まる連絡をする前に、プロポーザルをやったり、あるいは今までどこかにやっていただいたものに委託したりするのでしょうか。決めるのはどうするのかということが１つ。繰越明許費は、令和７年度のときに決裁して、言い方は変ですけれども、要するにお金が全部来るので、それを新年度になってからも支給していくので繰越明許費にならないという意味でいいのですか。","respondent":"柏木子育て応援課長","answer":"繰越明許費ですが、物価高対応子育て応援手当につきましては、３月３１日までに生まれた方になりますので、今年度予算で全て執行ができるという考えですので、繰越明許費については想定していません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどの転入のところは、１０月に引っ越してきた方は、品川区からいただけるのですか。児童手当をもらっているから。それとも、基準日を越えてしまっているので、物価高対応子育て応援手当支給については前の区に申請しないといけないのか。","respondent":"柏木子育て応援課長","answer":"基準日の９月３０日以降に転入された新生児につきましては、品川区で支給いたします。ですので、そのときに子育て応援課に児童手当の手続をしている方につきましては、品川区から支給になります。","voiceIndex":20,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"今また詳しく聞きたいのが、自分でも整理がつかないのですけれども、品川区から外へ出てしまっている方にも出していることも考えると、また複雑になるので、また後で詳しくお聞きします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"ここら辺が一番、心配事として、先ほどの質疑も含めてあるのだと思いますけれども、ここはどのように、仕組としていわゆる漏れなく担保されているか、お聞きしたい。","respondent":"柏木子育て応援課長","answer":"新生児の３月３１日ですとか、申請期限に近いときに生まれた方ですけれども、出生届自体が、１４日以内に提出しなければいけないことになってありますので、４月中旬までというと、２週間は当然、期間としてはありますので、その間に出生届と。","voiceIndex":29,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"決まりはそうですけれども、いろいろなご事情によって、４月中旬に出生届が出せなかった方がいた場合は、どういう扱いになるのでしょうか。","respondent":"柏木子育て応援課長","answer":"申請の期間につきまして、そこは状況を聞きながらとは考えてありますけれども、ただ６月以降とかに申請をされても、それは対応はできない。ですので、基本は申請期間内に申請をしていただく。ただ、そこは多少はご事情を聞きながら、対応はさせていただきたいと考えています。","voiceIndex":31,"id":"exchange-010"},{"speaker":"若林委員","kind":"意見","question":"いずれにしても、児童手当支給の対象の方ということで、年代もすごく、０歳から１８歳、広くて、ちょうどこの時期は、ただでさえ、入学、進学等の時期で、物価高騰対策ということで小学校はいろいろ無償化も進めていますけれども、それでもやはり準備にはお金がかかるので、一日でも早くお手元に届くように、最大限の努力をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-011"},{"speaker":"筒井副委員長","kind":"確認","question":"確認も含めて２点ほどお聞きしたいと思います。コールセンター、先ほど随意契約とおっしゃっていましたが、何かふだんから区が利用されている業者になるのか、補助率は国の１０分の１０ですけれども、コールセンターの業者については、各自治体、品川区なら品川区である程度、自由に決めていい、裁量で決めていいということなのでしょうか。その２点をお聞きしたいと思います。","respondent":"柏木子育て応援課長","answer":"１点目の所得制限ですが、この物価高対応子育て応援手当につきましては、所得制限はございません。次に、コールセンターの基準ですが、国から細かくは示されておりませんので、こうしなければいけないというものではございません。","voiceIndex":35,"id":"exchange-012"},{"speaker":"横山委員","kind":"確認","question":"再度、確認なのですけれども、先ほどの質問の中で、申請が必要な方の中に、他の自治体とかを見ますと、１０月１日から３月３１日までに離婚ですとか離婚調停中などによって、新たに児童手当の受給者となった方というような記載等もあるのですけれども、品川区の場合は、そのような方はどういった扱いになるのか教えてください。","respondent":"柏木子育て応援課長","answer":"離婚等で物価高対応子育て応援手当の受給者が変わる場合ですが、今、１月中旬に通知を予定していますので、そちらにその件はきちんと記載して、周知を図っていきたいと考えています。","voiceIndex":38,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどのお話はまた後でということで、コールセンターの話で今ほかの委員から質問があったのですけど、契約金額の上限は国から示されているのでしょうか。","respondent":"柏木子育て応援課長","answer":"今、手元にある資料では、そこら辺の金額の制限は特に見当たらないところです。","voiceIndex":41,"id":"exchange-014"},{"speaker":"筒井副委員長","kind":"質問","question":"コールセンターの経費が１,２４０万８,０００円、具体的に出ているのですけれど、これはどういう根拠でしょうか。","respondent":"柏木子育て応援課長","answer":"こちらは、資料では、システム・コールセンター経費で約１,２００万円を記載していますが、内訳といたしましては、コールセンターにつきましては約５００万円で、システム作業で約７００万円になってあります。","voiceIndex":43,"id":"exchange-015"},{"speaker":"つる委員長","kind":"質問・要望","question":"１月１６０万円ぐらいですね。３か月ぐらいと書いてありますから。最終的にどの自治体から支給されるということだけは、あえて私からも伺います。これは答弁の正確性も含めて、Ｑ＆Ａも確認いただきたいのですが、改めて私からも聞きます。児童手当自体は９月３０日ですよね。逆に１０月に入って転出した人は、品川区からの支給なのか、転出先の自治体からの支給なのか、そこを教えてください。","respondent":"柏木子育て応援課長","answer":"ですので、新生児で、１０月１日以降に他の自治体に転出された方は、転出された先の自治体から支給はされるという形であります。","voiceIndex":49,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7281#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":9109,"voices":62}},{"id":"r07-20251225-5","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"総務委員会","time":"午前１０時５０分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１４４号議案、令和７年度品川区一般会計補正予算","agenda":"第１４４号議案、令和７年度品川区一般会計補正予算","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"そこでお伺いしたいのですが、今回、プラス２,０００円、区独自でしてくださるということなのですけれども、こちらの経緯をお聞かせいただきたいということと、また、このギフト券なのですけれども、区内商品券というのは考え方としてあったのかどうかというのを教えていただければと思います。","respondent":"加島財政課長","answer":"区内の共通商品券を考えなかったのかですけれども、もちろん検討の俎上にはのってまいりました。","voiceIndex":6,"id":"exchange-001"},{"speaker":"西本委員","kind":"確認","question":"今の議論の中で、生活応援という形の中では２,０００円の上乗せ、そのために財政調整基金のほうからの繰入れというのが６.５億円あるという話で、そこら辺の東京都からの縛りはどういう、あまり縛りはなかったのですか。国から３,０００円程度というので下りてくるわけですよね。それから、国に対しては、これは１０分の１０なわけですよね。子育てについては。そこの確認をさせてください。","respondent":"加島財政課長、崎村企画課長","answer":"迅速かつ効率的・効果的に事業を執行することができるように、申請方式ではなく、プッシュ型で支援を行うこと、また、現金給付につきましても、個人を対象とした給付金につきましては、一律という形ではなくて、明確に対象範囲を設けて。それに上乗せするという形ですので、新たな組織をつくるということではなく、既存の組織での対応と考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"どういうふうに使われたのかということを調べるという、そこら辺で、どうやってやるのかなと思ったので、どこまでそれは要求されているのかというのを教えてください。それから、組織の中で心配なのは、新しい部署ということで、これは時限でいいのですか。これが終わったら戻るという形で、一応区切りがついたら組織改正は元に戻すという認識でよろしいのでしょうか。","respondent":"加島財政課長、崎村企画課長","answer":"５,０００円の中で幾らが使われて、きちんと生活者の下支えというところになったかどうかというのを把握できる、そういったギフトカードを使って制度設計、つまり事業設計をしていくようにと求められているところです。委員のご指摘のとおり、こちらの事業については、交付金を活用した限定的な事業となりますので、こちらの事業が完了しましたら、組織は解消するというような形で考えているところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"ギフトカードだから、今、想像ですが、ＱＵＯカードみたいなものを想定すると、それを使って、１,０００円を使った、次に２,０００円使ったという形になると、それがデータとして蓄積されるという、そういう形式を考えているというイメージなのですけれども、そういうのである程度、使った金額というのを把握できるという認識でよろしいですか。","respondent":"加島財政課長","answer":"その予定で、きちんとそういった国の交付の要件を満たせる事業者カードを探してまいりまして、区民の方のお手元にお届けしたいと考えております。","voiceIndex":14,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、区民生活の下支え、日々の暮らしに対して、生活ニーズに合わせて今回、ギフトカードということになったということをお聞きしましたが、これはほとんどのお店で使用が可能なのでしょうか。別のあれかもしれませんが、なぜできなかったのか。仮に振込にしたら、区民に渡る日数、また経費というのは大幅に削減できるのでしょうか。これは参考までにお聞きします。それについて教えてください。","respondent":"加島財政課長","answer":"期限を設けて、例えばですけれども、今日、区民委員会のほうでは、６か月程度の換金期限の想定ということでご説明していますが、換金期限が過ぎたら、例えば３,０００円残っていたけれども、それが失効してしまって使えなくなるのかというところにつきましては。","voiceIndex":16,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ答弁漏れがあったのですが、ギフトカード、皆さんに行き渡るのに、日数はどれぐらいかかるのですか。","respondent":"加島財政課長","answer":"区民の方のお手元に届くまでにというところなのですけれども、現在、プロポーザルで事業者は選定する予定です。","voiceIndex":18,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"確認","question":"全区民に５,０００円のギフト券と、子どもへの２万円の給付ということで補正予算なのですけれども、この全体の国が出した経済対策ということで様々メニューがある中で今回、品川区が、国は１人３,０００円程度と言っていたものに、３,０００円に２,０００円上乗せして、区としてはギフト券ということなのですけれども、私もホームページ等でメニューを見ると、様々、食料品だったり。","respondent":"加島財政課長","answer":"地域公共交通などにおきましても、区のほうで既に取り組んでいる、そういった状況を勘案しました結果、既に組んでいる既存の予算に充てるよりも、区民の方の物価高騰下における支援のほうに充てさせていただきたいということで、今回。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"提案","question":"よく分かりました。ですので、本当に物価対策というのであれば、私は最も効果が高く、国民が強く望む消費税の減税こそすべきだというのは、改めて意見として言っておきたいと思います。使用期限が設定できて、どれだけ使われたかを把握することというのを提案してきてくれる事業者というのは結構あるものなのですかというのを伺いたいのですが、区のほうで分かっていれば教えていただきたいと思います。","respondent":"加島財政課長","answer":"今回はスキームの中でそれが必要とされておりますので、事業者の数というのはかなり絞られてくると所管からは聞いております。具体的な数まではお答えができません。","voiceIndex":22,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほども、様々条件が設定された下でのこうした支援策ということで、本当にご苦労もあるだろうと。それで、そういうことが設定されることで、余計な支出が増えるのではないかという思いもあります。なので、国には柔軟で使いやすい、執行しやすい形をさらに求めていっていただきたいということは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"そうすると、区の独自財源としては、ざっくり２５億円の拠出というような試算になるかと考えていますが、この金額はどういう規模かというと、令和６年度の一般会計の決算では、６７億円が同年度予算の未消化で繰り越されるということになっていて、次年度の予算に繰り越されるということになっていましたので、そういった執行額を来年に繰り越すとなっている分を考慮すると、区予算を７,０００円上乗せして。","respondent":"加島財政課長","answer":"１人当たり１万円のというところで、７,０００円の上乗せについてというところにつきましてですが、もちろん私どものほうでも、こちらにさらなる上乗せを行うべきかどうかというのは検討させていただきました。","voiceIndex":25,"id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"ということですと、会派の緊急要望の中にも書かせていただきましたけれども、やはり効率的・効果的に区民の皆様に支援をしていくというところでいうと、そういった配布経費のところをいかに抑えて、支援額を高めていくかというところがありますので、マイナンバーカードと連携した活用とした給付方法でしたり、デジタル地域通貨の導入等で、一度プラットフォームをつくってしまえば、その都度。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"現金給付ということについて、一律はよくないというのがあったのですけれども、荒川区なんかはどうもやるようだと報道されていて、この２３区でも、ほかにも幾つか、現金の一律給付というのを考えているところがあるようですけれども、先ほどの答弁の中で、どれだけきちんと使われたか、その支出に使われたのかというのをきちんと検証できるようにという意味でいうと、現金というのは。","respondent":"加島財政課長","answer":"一律の現金給付、特に現金というところにつきましては、何かに使うにしても自由度が高いというところは確かに優れている点なのですが、コロナ禍で現金給付がございましたように、それが仮に消費ではなく貯蓄に回ったとしても。","voiceIndex":28,"id":"exchange-012"},{"speaker":"塚本副委員長","kind":"確認","question":"スケジュール的なところで、春頃というようなお話があったわけなのですけれども、区民委員会の資料を見ると、一応４月、５月が調達とかいろいろな準備などの期間というようなところにもなっていたのですが、この辺は、来年度４月ぐらいから、準備と並行して郵送も随時していくみたいなイメージで捉えても大丈夫ですか。どういうイメージでしょうか。そこだけ最後、確認させてください。","respondent":"加島財政課長","answer":"実際には、プロポーザルで事業者を選定してまいりますので、今、私どものほうで何月何日からとはっきり明言することが難しいのですけれども、区民委員会の資料にございました、発送前の準備に当たりまして、調達ができ次第。","voiceIndex":30,"id":"exchange-013"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"ほかに。いいですか。１回のことなのです。もっと言うと、こんなのが可能かどうか分からないけれども、自分たちの意思でふるさと納税とかやって、五十何億円も出ているわけではないですか。そういう人は渡さないとか、そういうことが法的に許されるかどうかは分からないけれども、そういうことだって何か考えていかないと、ただそういう人に対しては何か対策したいという気はあるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"}]},{"id":"topic-02","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"その中に分からないところがあったので、どういうことを示しているのかということを教えていただきたい、確認したいということです。流れとしては、例年どおり１月下旬、企画部から全議員に説明する、これは分かっています。それにもう一つ、「２月上旬、プレス発表。これは具体的にいうとどういうことなのか、よく分からないのです。これは具体的にどう変わるのかを確認させていただきたいということです。","respondent":"久保田企画経営部長","answer":"我々、その文章自体を直接見てはいないのですけれども、多分この間、会派説明のほうは、１月２９日にやっていただくということで日程をお知らせしたということです。そうですか。それとあと予算編成を、プレス発表を設定するとか、その日程を設定するということは我々区長部局のほうで決定しますので、そのことを表現された内容ではないかと考えています。","voiceIndex":44,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"これは非常に曖昧なので、具体的な行動が分からないのです。なので、具体的にどういうことなのかというのを教えてください。その後の対応については何の説明もないので、来年の予算説明もそういう状況になってしまうということになると、また私、動議をかけるぞと思っていますけれども、分かりやすいように、１月の総務委員会のときにはご説明いただければありがたいと思っていますので。","respondent":"久保田企画経営部長","answer":"以前の議案説明会で、田中議員から予算案の説明についての発言がありまして、その後、議長等とは私のほうで少しお話をして、議案説明会の日程の話とか、プレス発表までの資料の扱いの話は、企画経営部と区長室とでも話をしていますので、その文書をもう一度確認させた上で。","voiceIndex":50,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7289#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":18188,"voices":52}},{"id":"r07-20251225-10","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"議会運営委員会","time":"午後 １時２０分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7285#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":810,"voices":8}}]);
